+                        additional_native_plans.push(Arc::clone(swapped_join.children()[0]));
+                    }
+                    Ok((
+                        scans,
+                        shuffle_scans,
+                        Arc::new(SparkPlan::new_with_additional(
+                            spark_plan.plan_id,
