+// =============================================================================
+// Generator contract support
+//
+// The declarations below run the annotations-based code generator on the
+// checked-in annotated fixture (registry_generator_fixture.dart /
+// registry_generator_database_fixture.dart) and derive — from the actually
+// generated artifacts — the typed data adapter structure which the generated
+// typed database provides for its supported types. They deliberately inspect
+// only the shared language of the analyzer and the generated artifacts:
+// Dart declarations generated for the annotated document type, and registry
+// metadata declarations in the part of the generated output which was
+// emitted because the typed database was declared to support the document
+// type. No generated type name, internal helper class, enum member, or
+// literal wording is assumed.
+
+/// The `AssetId` under which the source of the checked-in annotated
+/// document fixture is served to the generator run.
+///
+/// The sources of the checked-in fixtures are served under the package of
+/// the annotations generator itself, so that the in-memory asset filesystem
+/// has access to the generator package's transitive dependencies (and in
+/// particular to `package:cbl`, which provides the annotations) without
+/// requiring a generated part file of the fixture to exist on disk: the
+/// test suite itself only ever compiles the fixtures' source as build
+/// input, never as an imported library.
+const String _genDocFixtureId =
+    'cbl_generator|lib/src/typed_data/registry_generator_fixture.dart';
+
+/// The `AssetId` under which the source of the checked-in annotated typed
+/// database fixture is served to the generator run.
+const String _genDatabaseFixtureId =
+    'cbl_generator|lib/src/typed_data/registry_generator_database_fixture.dart';
+
+/// The path, relative to the working directory of the test run (the
+/// `cbl_e2e_tests_standalone_dart` package), of the checked-in annotated
+/// document fixture.
+const _genDocFixtureSourcePath =
+    'test/cbl_e2e_tests/typed_data/registry_generator_fixture.dart';
+
+/// The path, relative to the working directory of the test run (the
+/// `cbl_e2e_tests_standalone_dart` package), of the checked-in annotated
+/// typed database fixture.
+const _genDatabaseFixtureSourcePath =
+    'test/cbl_e2e_tests/typed_data/registry_generator_database_fixture.dart';
+
+/// The declared name of the annotated document type of the checked-in
+/// document fixture.
+const String genDocName = 'GeneratorContractDoc';
+
+/// The declared name of the annotated typed database of the checked-in typed
+/// database fixture.
+const String genDatabaseName = r'$GeneratorContractDatabase';
+
+/// The shared in-memory asset filesystem of the generator run. The
+/// generated outputs of the run are read back through it, so that the
+/// contract tests only ever read actual generator output.
+final genTestAssetReaderWriter = TestReaderWriter(rootPackage: 'cbl_generator');
+
+/// The `AssetId` string of the typed-data output the generator emitted for
+/// the annotated document fixture.
+String genDocumentTypeOutputId = '';
+
+/// The `AssetId` string of the typed-database output the generator emitted
+/// for the annotated typed database fixture.
+String genDatabaseOutputId = '';
+
+Future<TestBuilderResult>? _generatorRun;
+
+/// Starts the (single) generator run over the checked-in fixtures and
+/// returns its result. All generator contract tests share the same in-flight
+/// run, so the generator runs exactly once for the whole suite.
+Future<TestBuilderResult> ensureGeneratorRunAsync() =>
+    _generatorRun ??= _runGeneratorOnce();
+
+Future<TestBuilderResult> _runGeneratorOnce() async {
+  // Read the checked-in annotated fixture files from the source tree and
+  // deliver them as build sources of the annotations generator's own
+  // package, then run the real annotations generator builders over them.
+  final docSource = File(_genDocFixtureSourcePath).readAsStringSync();
+  final dbSource = File(_genDatabaseFixtureSourcePath).readAsStringSync();
+
+  final result = await testBuilders(
+    [TypedDataBuilder(), TypedDatabaseBuilder()],
+    {_genDocFixtureId: docSource, _genDatabaseFixtureId: dbSource},
+    rootPackage: 'cbl_generator',
+    readerWriter: genTestAssetReaderWriter,
+    flattenOutput: true,
+  );
+
+  // Discover the emitted outputs from the result of the run: the typed-data
+  // output is the output emitted because of the annotated document fixture;
+  // the typed-database output is the one emitted because of the annotated
+  // typed database fixture. Only their membership in the run result and
+  // their association with the fixture is used — not a particular generated
+  // asset path.
+  genDocumentTypeOutputId = result.outputs
+      .map((id) => id.toString())
+      .where((id) => id.contains('registry_generator_fixture'))
+      .single;
+  genDatabaseOutputId = result.outputs
+      .map((id) => id.toString())
+      .where((id) => id.contains('registry_generator_database_fixture'))
+      .single;
+
+  return result;
+}
