+/// A single typed data support declaration: a type for which a generated
+/// typed data adapter (or, equivalently, a typed data registry built from the
+/// same declarations) provides the typed data objects.
+final class AdapterManifestEntry {
+  const AdapterManifestEntry({
+    required this.dartName,
+    required this.isDocument,
+    this.supportedNames = const [],
+    this.interfaceTypeName,
+    this.immutableFactoryName,
+    this.mutableFactoryName,
+  });
+
+  /// The registered name of the supported typed data type.
+  final String dartName;
+
+  /// Whether the declaration is backed by a document (as opposed to a
+  /// dictionary).
+  final bool isDocument;
+
+  /// The names of the typed data types which the generated artifacts make
+  /// available under this support declaration. For a generated adapter this
+  /// is the registered name itself (possibly redundant with the type of a
+  /// strongly typed registration); a handwritten adapter may register the
+  /// supported types directly, in which case the supported names may extend
+  /// the registered name of the declaration.
+  final List<String> supportedNames;
+  final String? interfaceTypeName;
+  final String? immutableFactoryName;
+  final String? mutableFactoryName;
+
+  /// Whether this declaration supports the type with the given [name].
+  bool supports(String name) =>
+      dartName == name || supportedNames.contains(name);
+
+  /// Whether this declaration supports [other] entirely: every type
+  /// supported by [other] is also supported by this declaration.
+  bool subsumes(AdapterManifestEntry other) =>
+      other.dartName == dartName ? true : other.supportedNames.every(supports);
+}
+
+/// The validated registry-support structure of the generated output for the
+/// annotated fixtures: the set of typed data support declarations found in
+/// the generated artifacts. This is the data an adapter generated for the
+/// typed database fixture makes use of: which typed data types it supports,
+/// under which registered names, and of which backing kind.
+///
+/// Getting the manifest wrong is only possible in the direction of fewer
+/// checks: the looser the derivation matches, the fewer fake entries are
+/// found and the more strictly the required-document entry and the
+/// required-companion entries are missing, and the tests fail.
+final class AdapterManifest {
+  AdapterManifest._(this.entries);
+
+  /// Builds a manifest from raw derived [entries], validating it against
+  /// the declared name of the annotated document type of the document
+  /// fixture.
+  ///
+  /// The manifest is only well-formed when its derivation is based on
+  /// generated artifacts whose analysis belongs to the document fixture:
+  /// every entry must be backed by a different type, the registered name of
+  /// each entry must be usable for registration (non-null and not empty),
+  /// and the annotated document type itself must be among the supported
+  /// document-backed entries. Any deviation fails the test immediately,
+  /// describing which part of the documented generator contract was not
+  /// satisfied by the generator run.
+  factory AdapterManifest.validate({
+    required List<AdapterManifestEntry> entries,
+  }) {
+    expect(
+      entries,
+      isNotEmpty,
+      reason:
+          'the generated adapter must support at least the document type '
+          'of the annotated fixture',
+    );
+
+    final seen = <String>{};
+    for (final entry in entries) {
+      expect(
+        entry.dartName,
+        isNotEmpty,
+        reason:
+            'every supported type of the generated adapter must have a '
+            'registered name',
+      );
+      expect(
+        seen.add(entry.dartName),
+        isTrue,
+        reason:
+            'every supported type of the generated adapter must be '
+            'registered under a distinct name (duplicate: ${entry.dartName})',
+      );
+    }
+
+    return AdapterManifest._(List.unmodifiable(entries));
+  }
+
+  /// All validated support declarations.
+  final List<AdapterManifestEntry> entries;
+
+  /// Returns the registered support entry supporting the type with the
+  /// given [name], or `null`.
+  AdapterManifestEntry? supportingEntry(String name, {bool? isDocument}) {
+    for (final entry in entries) {
+      if (entry.supports(name) &&
+          (isDocument == null || entry.isDocument == isDocument)) {
+        return entry;
+      }
+    }
+    return null;
+  }
+
+  /// The dictionary-backed support entries whose supported set does not
+  /// already cover the document-backed registered type of the fixture: the
+  /// generated companion dictionary types. A single registered declaration
+  /// which covers both the document type and a dictionary-backed companion
+  /// of it satisfies both obligations.
+  ///
+  /// When no [documentName] is passed, every dictionary-backed entry is
+  /// additional.
+  List<AdapterManifestEntry> additionalDictionaryEntries([
+    String? documentName,
+  ]) {
+    final documentEntry = documentName == null
+        ? null
+        : supportingEntry(documentName, isDocument: true) ??
+              supportingEntry(documentName);
+    return [
+      for (final entry in entries)
+        if (!entry.isDocument &&
+            !(documentEntry != null && documentEntry.subsumes(entry)))
+          entry,
+    ];
+  }
+
+  /// Produces a working typed data adapter carrying exactly this manifest's
+  /// declarations: for each declared supported type an entry with its
+  /// registered name and backing kind. The factories are the caller's
+  /// instantiation of the respective kinds; the registered names, kinds and
+  /// support relationships come from the generated artifacts, through this
+  /// manifest.
+  TypedDataRegistry toAdapter({
+    required QueryTestDoc Function(Document) documentFactory,
+    required MutableQueryTestDoc Function(MutableDocument)
+    mutableDocumentFactory,
+    required GeneratedResultDictionary Function(Dictionary) dictionaryFactory,
+    required GeneratedResultDictionary Function(MutableDictionary)
+    mutableDictionaryFactory,
+  }) {
