+        types.add(
+          TypedDocumentMetadata<QueryTestDoc, MutableQueryTestDoc>(
+            dartName: entry.dartName,
+            factory: documentFactory,
+            mutableFactory: mutableDocumentFactory,
+          ),
+        );
+      } else {
+        types.add(
+          TypedDictionaryMetadata<
+            GeneratedResultDictionary,
+            GeneratedResultDictionary
+          >(
+            dartName: entry.dartName,
+            factory: dictionaryFactory,
+            mutableFactory: mutableDictionaryFactory,
+          ),
+        );
+      }
+    }
+
+    return TypedDataRegistry(types: types);
+  }
+}
+
+/// Derives the registry-support declarations which the generated output of
+/// the annotations generator contains for the annotated fixtures.
+///
+/// [typeOutput] is the typed-data output emitted for the annotated document
+/// fixture of the generator run; [adapterOutput] is the typed-database
+/// output emitted for the annotated typed database fixture. The derivation
+/// is based on the shared language of the analyzer and the generated
+/// artifacts only:
+///
+///  - the declaration of a named type, in the analyzer language, is matched
+///    by a `class` declaration of the name;
+///  - registry-support declarations, in the generated artifacts, are found
+///    in the part of the generated typed-database output which was emitted
+///    because the typed database was declared to support the document type:
+///    a support declaration is a generated typed data metadata declaration,
+///    defaulted to a document-backed declaration for the document type of
+///    the fixture, and dictionary-backed declarations are the additional
+///    supported types whose generated typed data classes are emitted in the
+///    typed-data output of the document fixture.
+///
+/// Any support declaration whose registered name cannot be derived is either
+/// rejected (when [requireNonNullRegistryManifestFields] is `true`) or
+/// silently ignored. `registry_test.dart` always passes `true`; the other
+/// mode documents that the derivation of a missing name must never be wired
+/// to a fixed value in its place.
+List<AdapterManifestEntry> registryManifestEntriesFor(
+  String adapterOutput, {
+  bool requireNonNullRegistryManifestFields = false,
+}) {
+  final entries = <AdapterManifestEntry>[];
+
+  // The generated adapter's metadata declarations identify both the
+  // registered Dart type and whether it is backed by a document or a
+  // dictionary. Use those declarations rather than guessing from a type
+  // name: companion dictionary names are not required to share a prefix
+  // with the document name.
+  final declarations = RegExp(
+    r'Typed(Document|Dictionary)Metadata\s*<\s*([^,>]+)\s*,\s*([^>]+)>\s*\((.*?)\)',
+    dotAll: true,
+  ).allMatches(_adapterMetadataRegionOf(adapterOutput));
+
+  for (final declaration in declarations) {
+    final isDocument = declaration[1] == 'Document';
+    final immutableName = declaration[2]!.trim();
+    final mutableName = declaration[3]!.trim();
+    final body = declaration[4]!;
+    final nameMatch = RegExp(r"dartName:\s*'([^']+)'").firstMatch(body);
+    final factoryName = RegExp(
+      r'factory:\s*([A-Za-z_$][A-Za-z0-9_$]*)\.internal',
+    ).firstMatch(body);
+    final mutableFactoryName = RegExp(
+      r'mutableFactory:\s*([A-Za-z_$][A-Za-z0-9_$]*)\.internal',
+    ).firstMatch(body);
+
+    if (nameMatch == null ||
+        factoryName == null ||
+        mutableFactoryName == null) {
+      if (requireNonNullRegistryManifestFields) {
+        expect(
+          nameMatch,
+          isNotNull,
+          reason: 'generated typed-data registrations must expose a name',
+        );
+      }
+      continue;
+    }
+
+    final registeredName = nameMatch[1]!;
+    entries.add(
+      AdapterManifestEntry(
+        dartName: registeredName,
+        isDocument: isDocument,
+        supportedNames: {
+          registeredName,
+          immutableName,
+          mutableName,
+          if (isDocument) genDocName,
+        }.toList(),
+        interfaceTypeName: immutableName,
+        immutableFactoryName: factoryName[1],
+        mutableFactoryName: mutableFactoryName[1],
+      ),
+    );
+  }
+
+  return entries;
+}
