+/// The region of the generated adapter output in which the typed data
+/// support declarations of the adapter are located: the part of the output
+/// which follows its typed data adapter declaration.
+String _adapterMetadataRegionOf(String adapterOutput) {
+  final metadata = RegExp(
+    r'Typed(?:Document|Dictionary)Metadata\s*<',
+  ).firstMatch(adapterOutput);
+  if (metadata != null) {
