@@ -22,13 +22,118 @@ void main() {
   testAllTestData(allTestData, schemaUri, schema);

   final dataUri = testDataUri.resolve('recorded_uses.json');
+  final data = allTestData[dataUri]!;
+
+  group('Constant wire tags', () {
+    // Build a synthetic document containing exactly one constant, so the
+    // checks do not rely on any particular fixture's variant inventory.
+    final template = jsonDecode(data) as Map<String, Object?>;
+
+    Map<String, Object?> documentWithConstant(
+      Map<String, Object?> constant,
+    ) => <String, Object?>{
+      ...template,
+      'constants': [constant],
+    };
+
+    void expectValid(Map<String, Object?> document) {
+      final result = schema.validate(document);
+      printOnFailure(result.errors.join('\n'));
+      expect(result.isValid, isTrue);
+    }
+
+    void expectInvalid(Map<String, Object?> document) {
+      final result = schema.validate(document);
+      expect(result.isValid, isFalse);
+    }
+
+    for (final type in [
+      'bool',
+      'int',
+      'instance',
+      'list',
+      'map',
+      'null',
+      'string',
+    ]) {
+      test('schema accepts the "$type" tag', () {
+        expectValid(
+          documentWithConstant(
+            type == 'null'
+                ? {'type': 'null'}
+                : type == 'instance'
+                ? {'type': 'instance', 'value': <String, Object?>{}}
+                : type == 'bool'
+                ? {'type': 'bool', 'value': true}
+                : type == 'int'
+                ? {'type': 'int', 'value': 42}
+                : type == 'list'
+                ? {'type': 'list', 'value': <Object?>[]}
+                : type == 'map'
+                ? {'type': 'map', 'value': <String, Object?>{}}
+                : {'type': 'string', 'value': 'hello'},
+          ),
+        );
+      });
+    }
+
+    for (final (type, wrongValue) in [
+      ('bool', 'not-a-bool'),
+      ('int', 'not-an-int'),
+      ('list', 'not-a-list'),
+      ('map', 'not-a-map'),
+    ]) {
+      test('schema rejects a wrong value type for the "$type" tag', () {
+        expectInvalid(
+          documentWithConstant({'type': type, 'value': wrongValue}),
+        );
+      });
+    }
+
+    test('schema rejects a wrong value type for the "string" tag', () {
+      expectInvalid(
+        documentWithConstant({'type': 'string', 'value': 42}),
+      );
+    });
+
+    test('schema rejects a value for the "null" tag', () {
+      expectInvalid(
+        documentWithConstant({'type': 'null', 'value': true}),
+      );
+    });
+
+    test('schema rejects a wrong value type for the "instance" tag', () {
+      expectInvalid(
+        documentWithConstant({'type': 'instance', 'value': 42}),
+      );
+    });
+
+    // Note: required-`value` enforcement for the five tags whose `value`
+    // is mandatory is covered by the `constants.N.value missing` tests in
+    // `recordUseFields` below. Those tests derive their invalid documents
+    // by removing `value` from the existing fixture constants, which
+    // deliberately leaves the `type` tag itself valid, so they do not
+    // constrain how the schema expresses the required-value rule
+    // internally.
+
+    // Forward compatibility: the schema tolerates type tags outside the
+    // seven known ones, including the retired spellings and unrelated
+    // future spellings.
+    for (final type in ['String', 'Record']) {
+      test('schema tolerates the unknown "$type" tag', () {
+        expectValid(
+          documentWithConstant({'type': type, 'value': 'anything'}),
+        );
+      });
+    }
+  });

   for (final field in recordUseFields) {
     testField(
       schemaUri: schemaUri,
       dataUri: dataUri,
       schema: schema,
-      data: allTestData[dataUri]!,
+      data: data,
       field: field.$1,
       missingExpectations: field.$2,
     );
