+  group('constant wire tags', () {
+    final indexOf = <Constant>[];
+
+    Constant decode(Map<String, Object?> constantJson) =>
+        Constant.fromJson(constantJson, indexOf);
+
+    void expectRoundTrip(
+      Constant constant,
+      Map<String, Object?> expectedJson,
+    ) {
+      final index = {
+        for (var i = 0; i < indexOf.length; i++) indexOf[i]: i,
+      };
+      expect(constant.toJson(index), expectedJson);
+
+      // Only JSON maps can be deserialized again; the constant table uses
+      // integer indices pointing into a shared table.
+      final decoded = decode(json.decode(json.encode(expectedJson))
+          as Map<String, Object?>);
+      expect(decoded, constant);
+    }
+
+    test('StringConstant uses the "string" wire tag', () {
+      expectRoundTrip(const StringConstant('hello'), {
+        'type': 'string',
+        'value': 'hello',
+      });
+    });
+
+    test('NullConstant uses the "null" wire tag', () {
+      expectRoundTrip(const NullConstant(), {'type': 'null'});
+    });
+
+    test('an empty InstanceConstant omits the value', () {
+      expectRoundTrip(const InstanceConstant(fields: {}), {
+        'type': 'instance',
+      });
+    });
+
+    test('an InstanceConstant serializes its fields', () {
+      indexOf.addAll([const IntConstant(42), const NullConstant()]);
+      expectRoundTrip(
+        const InstanceConstant(
+          fields: {'a': IntConstant(42), 'b': NullConstant()},
+        ),
+        {
+          'type': 'instance',
+          // Field values are normalized into the shared constant table.
+          'value': {'a': 0, 'b': 1},
+        },
+      );
+    });
+
+    test('the retired "String" wire tag is rejected', () {
+      expect(() => decode({'type': 'String'}), throwsA(anything));
+    });
+
+    test('the retired "Null" wire tag is rejected', () {
+      expect(() => decode({'type': 'Null'}), throwsA(anything));
+    });
+
+    test('the retired "Instance" wire tag is rejected', () {
+      expect(() => decode({'type': 'Instance'}), throwsA(anything));
+    });
+  });
+
