+            ..writeln('    } on FormatException {')
+            ..writeln('      // Direct construction rejects values outside the set.')
+            ..writeln('    }')
+            ..writeln('    try {')
+            ..writeln('      final parsed = NovaGroup.fromJson(v);')
+            ..writeln('      if (NovaGroup.fromJson(v).toJson() != v) {')
+            ..writeln(r"        throw StateError('fromJson must round-trip $v');")
+            ..writeln('      }')
+            ..writeln('      accepted.add(v);')
+            ..writeln('      if (parsed.toJson() == v) roundTripped.add(v);')
+            ..writeln('    } on FormatException {')
+            ..writeln('      // Out-of-set rejection, the contract shape.')
+            ..writeln('    }')
+            ..writeln('  }')
+            ..writeln('  final maybeNull = NovaGroup.maybeFromJson(null);')
+            ..writeln('  print(jsonEncode({')
+            ..writeln("    'accepted': accepted,")
+            ..writeln("    'directAccepted': directAccepted,")
+            ..writeln("    'roundTripped': roundTripped,")
+            ..writeln("    'maybe4': NovaGroup.maybeFromJson(4)?.toJson(),")
+            ..writeln("    'maybeNull': maybeNull == null,")
+            ..writeln('  }));')
+            ..writeln('}');
+          // The probe must resolve the support template's own imports, so it
+          // runs inside this package (albeit in a scratch subdirectory the
+          // test removes afterwards).
+          final probeDir = Directory.current.createTempSync(
+            'int_enum_membership',
+          );
+          addTearDown(() => probeDir.deleteSync(recursive: true));
+          final probeFile = File('${probeDir.path}/probe.dart')
+            ..writeAsStringSync(probe.toString());
+          final run = await Process.run(Platform.resolvedExecutable, [
+            probeFile.path,
+          ]).timeout(const Duration(minutes: 1));
+          expect(
+            run.exitCode,
+            0,
+            reason:
+                'emitted declaration must compile and run against the '
+                'generated-support template:\n$probe\n${run.stderr}',
+          );
+          final report =
+              jsonDecode((run.stdout as String).trim()) as Map<String, dynamic>;
+          expect(
+            [...(report['accepted'] as List).cast<int>()]..sort(),
+            orderedEquals(members),
+            reason:
+                'the emitted validation must accept exactly $members; '
+                'declaration:\n$body',
+          );
+          expect(
+            [...(report['directAccepted'] as List).cast<int>()]..sort(),
+            orderedEquals(members),
+            reason: 'direct construction accepts exactly the declared set',
+          );
+          expect(
+            [...(report['roundTripped'] as List).cast<int>()]..sort(),
+            orderedEquals(members),
+            reason: 'every member round-trips',
+          );
+          expect(
+            report['maybe4'],
+            4,
+            reason: 'maybeFromJson accepts a member and round-trips it',
+          );
+          expect(
+            report['maybeNull'],
+            isTrue,
+            reason: 'maybeFromJson(null) returns null',
+          );
+        }
+      },
+    );
+    },
+    // The group compiles and runs the probe in fresh Dart processes; give it
+    // more room than the default 30-second test timeout.
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
 }
