+Future<Response> _callWithLogging(Handler handler, Request request) async =>
+    createLoggingMiddleware()(handler)(request);
+
+/// Reads all SSE data events written to [response], ignoring keep-alives.
+Future<List<Object>> _drainSseEvents(CallableResponse<dynamic> response) async {
+  final events = <Object>[];
+  final body = await utf8.decoder
+      .bind(response.streamingResponse!.read())
+      .join();
+  for (final frame in body.split('\n\n')) {
+    final trimmed = frame.trim();
+    if (trimmed.isEmpty || trimmed.startsWith(':')) {
+      continue;
+    }
+    events.add(jsonDecode(trimmed.substring('data: '.length)) as Object);
+  }
+  return events;
+}

