+/// Reads the added offer-list property dynamically so the base version can
+/// execute an assertion for the absent behavior instead of failing compilation.
+List<dynamic>? readOneTimeOfferList(Object product) {
+  final dynamic dynamicProduct = product;
+  try {
+    return dynamicProduct.oneTimePurchaseOfferDetailsList as List<dynamic>?;
+  } on NoSuchMethodError {
+    fail('The wrapper must expose its one-time purchase offer list.');
+  }
+}
