+#!/usr/bin/env python3
+"""Convert Flutter JSON test events into complete, parser-visible test records."""
+import json
+import sys
+from pathlib import Path
+
+
+def adapt(lines):
+    suites = {}
+    starts = {}
+    errors = {}
+    completed = []
+    saw_done = False
+    saw_protocol = False
+    command_errors = []
+    diagnostics = []
+
+    for line_number, raw in enumerate(lines, 1):
+        text = raw.strip()
+        if not text:
+            continue
+        try:
+            event = json.loads(text)
+        except json.JSONDecodeError as error:
+            if not saw_protocol:
+                # Flutter may print dependency/bootstrap notices before the JSON stream.
+                diagnostics.append(text)
+                continue
+            if saw_done or not text.startswith("{"):
+                # Flutter can write human-readable diagnostics alongside its JSON
+                # reporter output. Preserve them while the event stream remains checked.
+                diagnostics.append(text)
+                continue
+            command_errors.append(f"malformed Flutter JSON event at line {line_number}: {error}")
+            continue
+        saw_protocol = True
+        if not isinstance(event, dict) or not isinstance(event.get("type"), str):
+            command_errors.append(f"invalid Flutter event at line {line_number}")
+            continue
+        kind = event["type"]
+        if saw_done:
+            command_errors.append(f"Flutter event occurred after done at line {line_number}")
+            continue
+        if kind == "suite":
+            suite = event.get("suite", {})
+            if isinstance(suite, dict) and "id" in suite:
+                suites[suite["id"]] = suite.get("path", "")
+        elif kind == "testStart":
+            test = event.get("test", {})
+            if not isinstance(test, dict) or "id" not in test:
+                command_errors.append(f"testStart without an ID at line {line_number}")
+                continue
+            test_id = test["id"]
+            metadata = test.get("metadata") or {}
+            suite_path = suites.get(test.get("suiteID"))
+            if suite_path is None:
+                command_errors.append(f"testStart references an unknown suite at line {line_number}")
+                continue
+            starts[test_id] = (
+                test.get("name", ""),
+                suite_path,
+                bool(metadata.get("skip")),
+                bool(test.get("hidden")),
+            )
+        elif kind == "error":
+            test_id = event.get("testID")
+            if test_id in starts:
+                message = event.get("error", "test error")
+                errors.setdefault(test_id, []).append(message)
+                stack = event.get("stackTrace")
+                diagnostics.append(f"{message}\n{stack}" if stack else message)
+            else:
+                command_errors.append(event.get("error", "unattributed Flutter test error"))
+        elif kind == "testDone":
+            test_id = event.get("testID")
+            if test_id not in starts:
+                command_errors.append(f"testDone without a matching start at line {line_number}")
+                continue
+            name, path, skipped_by_metadata, hidden = starts.pop(test_id)
+            result = event.get("result")
+            skipped = skipped_by_metadata or bool(event.get("skipped")) or result == "skipped"
+            hidden = hidden or bool(event.get("hidden"))
+            test_errors = errors.pop(test_id, [])
+            failed = result in ("failure", "error") or bool(test_errors)
+            if not skipped and not hidden and name and not _is_lifecycle(name):
+                completed.append((path, name, failed))
+            elif failed:
+                command_errors.append(f"Flutter lifecycle test failed: {name}")
+        elif kind == "done":
+            saw_done = True
+        # Other JSON protocol events are lifecycle/progress metadata, not test IDs.
+
+    if not saw_protocol:
+        command_errors.append("No Flutter JSON events found")
+    if not saw_done:
+        command_errors.append("Flutter JSON stream ended without a done event")
+    if starts:
+        command_errors.append("Flutter JSON stream ended with tests lacking completion")
+    if errors:
+        command_errors.append("Flutter JSON stream ended with uncompleted test errors")
+    pass_count = 0
+    fail_count = 0
+    records = []
+    for path, name, failed in completed:
+        identity = f"{path}: {name}" if path else name
+        if failed:
+            fail_count += 1
+            records.append(f"00:00 +{pass_count} -{fail_count}: {identity} [E]")
+        else:
+            pass_count += 1
+            records.append(f"00:00 +{pass_count}: {identity}")
+    return records, command_errors, diagnostics
+
+
+def _is_lifecycle(name):
+    return name.strip() in ("(setUpAll)", "(tearDownAll)", "setUpAll", "tearDownAll")
+
+
+def _self_test():
+    def event(kind, **fields):
+        return json.dumps({"type": kind, **fields})
+
+    interleaved = [
+        event("suite", suite={"id": 1, "path": "alpha_test.dart"}),
+        event("suite", suite={"id": 2, "path": "beta_test.dart"}),
+        event("testStart", test={"id": 10, "name": "quick pass", "suiteID": 1}),
+        event("testStart", test={"id": 20, "name": "failure", "suiteID": 2}),
+        event("testStart", test={"id": 30, "name": "skip", "suiteID": 1}),
+        event("error", testID=20, error="expected failure"),
+        event("testDone", testID=10, result="success", skipped=False),
+        event("testDone", testID=20, result="failure", skipped=False),
+        event("testDone", testID=30, result="skipped", skipped=True),
+        event("done", success=False),
+    ]
+    records, errors, diagnostics = adapt(interleaved)
+    if errors or diagnostics != ["expected failure"] or len(records) != 2:
+        return False
+    if not any("alpha_test.dart: quick pass" in line for line in records):
+        return False
+    if not any("beta_test.dart: failure [E]" in line for line in records):
+        return False
+    if any("skip" in line for line in records):
+        return False
+    interrupted = [
+        event("suite", suite={"id": 1, "path": "interrupted_test.dart"}),
+        event("testStart", test={"id": 40, "name": "never completed", "suiteID": 1}),
+    ]
+    _, errors, _ = adapt(interrupted)
+    if not errors:
+        return False
+    malformed = [
+        event("suite", suite={"id": 1, "path": "malformed_test.dart"}),
+        event("testStart", test={"id": 50, "name": "malformed event", "suiteID": 1}),
+        "{not valid JSON",
+        event("testDone", testID=50, result="success", skipped=False),
+        event("done", success=True),
+    ]
+    _, errors, _ = adapt(malformed)
+    return any("malformed Flutter JSON" in error for error in errors)
+
+
+def main():
+    if len(sys.argv) == 2 and sys.argv[1] == "--self-test":
+        if _self_test():
+            return 0
+        print("Flutter event-adapter self-check failed", file=sys.stderr)
+        return 1
+    if len(sys.argv) != 2:
+        print("usage: report_flutter_results.py <flutter-json-log>", file=sys.stderr)
+        return 2
+    try:
+        lines = Path(sys.argv[1]).read_text(errors="replace").splitlines()
+    except OSError as error:
+        print(f"Unable to read Flutter test log: {error}", file=sys.stderr)
+        return 2
+    if not _self_test():
+        print("Flutter event-adapter self-check failed", file=sys.stderr)
+        return 2
+    records, errors, diagnostics = adapt(lines)
+    for record in records:
+        print(record)
+    for diagnostic in diagnostics:
+        print(diagnostic, file=sys.stderr)
+    for error in errors:
+        print(error, file=sys.stderr)
+    return 2 if errors else 0
+
+
+if __name__ == "__main__":
+    sys.exit(main())
