+#!/usr/bin/env python3
+"""Translate actual Android JUnit XML results into parser-visible progress lines.
+
+The task's configured result parser recognizes Flutter progress records. Android
+unit tests are run by Gradle, whose authoritative per-test results are JUnit XML;
+this adapter preserves each JUnit testcase identifier and reports only actual
+passed tests or JUnit assertion failures. Compilation/setup errors and skipped
+tests are intentionally not represented as passed/failed test cases.
+"""
+
+from pathlib import Path
+import sys
+import xml.etree.ElementTree as ET
+
+
+def main() -> int:
+    if len(sys.argv) != 2:
+        print("usage: report_native_junit_results.py <test-results-directory>", file=sys.stderr)
+        return 2
+    report_dir = Path(sys.argv[1])
+    files = sorted(report_dir.glob("TEST-*.xml")) if report_dir.is_dir() else []
+    counter = 0
+    for report in files:
+        try:
+            root = ET.parse(report).getroot()
+        except (ET.ParseError, OSError) as error:
+            print(f"Unable to read JUnit report {report}: {error}", file=sys.stderr)
+            return 2
+        for case in root.iter("testcase"):
+            # A JUnit testcase ID is the actual class and test method reported
+            # by Gradle, not a synthesized name or private test selection.
+            class_name = case.attrib.get("classname", "")
+            test_name = case.attrib.get("name", "")
+            if not test_name:
+                continue
+            test_id = f"{class_name}.{test_name}" if class_name else test_name
+            failure = case.find("failure")
+            if failure is None:
+                # Errors, skips, and incomplete tests are deliberately not
+                # mapped to successful or behavioral-failure IDs.
+                if case.find("error") is not None or case.find("skipped") is not None:
+                    continue
+                counter += 1
+                print(f"00:00 +{counter}: {test_id}")
+            else:
+                counter += 1
+                print(f"00:00 +{counter - 1} -1: {test_id} [E]")
+    if not files:
+        print(f"No Android JUnit XML reports found in {report_dir}", file=sys.stderr)
+        return 2
+    return 0
+
+
+if __name__ == "__main__":
+    raise SystemExit(main())
