+void main() {
+  group('Billing Library migration contract', () {
+    test('uses Billing Library 8 and its product-details result callback', () {
+      final String buildFile = File(
+        'android/build.gradle.kts',
+      ).readAsStringSync();
+      final String dartWrapper = File(
+        'lib/src/billing_client_wrappers/billing_client_wrapper.dart',
+      ).readAsStringSync();
+
+      expect(buildFile, contains('com.android.billingclient:billing:8.0.0'));
+      expect(
+        RegExp(r'\bqueryPurchaseHistory\s*\(').hasMatch(dartWrapper),
+        isFalse,
+      );
+      final String pigeonMessages = File(
+        'pigeons/messages.dart',
+      ).readAsStringSync();
+      expect(
+        RegExp(r'\bqueryPurchaseHistoryAsync\s*\(').hasMatch(pigeonMessages),
+        isFalse,
+      );
+      expect(
+        RegExp(r'\bqueryPurchasesAsync\s*\(').hasMatch(pigeonMessages),
+        isTrue,
+      );
+    });
+
+    test(
+      'migration documentation directs history callers to active purchases',
+      () {
+        final Directory package = Directory('.');
+        final List<String> passages = <String>[];
+        for (final FileSystemEntity entity in package.listSync(
+          recursive: true,
+        )) {
+          if (entity is! File ||
+              (!entity.path.endsWith('.md') &&
+                  !entity.path.endsWith('.dart')) ||
+              entity.path.contains('/.dart_tool/') ||
+              entity.path.contains('/build/')) {
+            continue;
+          }
+          final String contents = entity.readAsStringSync();
+          if (entity.path.endsWith('.md')) {
+            passages.addAll(contents.split(RegExp(r'\n\s*\n')));
+            continue;
+          }
+          final RegExp docComment = RegExp(
+            r'((?:^|\n)(?:\s*///[^\n]*\n)+)([\s\S]{0,500})',
+            multiLine: true,
+          );
+          for (final RegExpMatch match in docComment.allMatches(contents)) {
+            final String documentedDeclaration = match.group(2)!;
+            if (RegExp(
+              r'\bqueryPurchases\s*\(',
+            ).hasMatch(documentedDeclaration)) {
+              passages.add('${match.group(1)} queryPurchases');
+            }
+          }
+        }
+
+        final bool documentsReplacement = passages.any((String passage) {
+          final String normalized = passage
+              .replaceAll('`', ' ')
+              .replaceAll(RegExp(r'\s+'), ' ')
+              .toLowerCase();
+          final bool namesPurchaseHistory =
+              normalized.contains('querypurchasehistory') ||
+              RegExp(r'purchase[ -]history|history query').hasMatch(normalized);
+          final bool namesReplacement = normalized.contains('querypurchases');
+          final bool givesDirection = RegExp(
+            r'\b(instead|use|replace|replacement|switch|migrate|should|direct|replaces)\b',
+          ).hasMatch(normalized);
+          return namesPurchaseHistory && namesReplacement && givesDirection;
+        });
+        expect(documentsReplacement, isTrue);
+      },
+    );
+  });
+}
