+// Pigeon test values are decoded through the generated message codec, while
+// the unfetched element type is discovered by its public productId data rather
+// than by naming an internal generated type.
+
+/// Builds a platform query result by decoding the Pigeon response wire value.
+/// This avoids binding test source to a generated element type or constructor
+/// field name, while exercising the actual platform-message model.
+PlatformProductDetailsResponse platformResponseForTest({
+  required PlatformBillingResponse responseCode,
+  String debugMessage = 'dummy message',
+  int subResponseCode = 0,
+  List<PlatformProductDetails> productDetails =
+      const <PlatformProductDetails>[],
+  List<dynamic> unfetchedProducts = const <dynamic>[],
+}) {
+  final PlatformBillingResult billingResult = PlatformBillingResultStub(
+    responseCode,
+    debugMessage,
+    subResponseCode: subResponseCode,
+  );
+  for (int typeTag = 128; typeTag <= 255; typeTag++) {
+    final WriteBuffer buffer = WriteBuffer();
+    buffer.putUint8(typeTag);
+    final dynamic codec = InAppPurchaseApi.pigeonChannelCodec;
+    codec.writeValue(buffer, <Object?>[
+      billingResult,
+      productDetails,
+      unfetchedProducts,
+    ]);
+    try {
+      final Object? decoded = codec.decodeMessage(buffer.done());
+      if (decoded is PlatformProductDetailsResponse) {
+        return decoded;
+      }
+    } on Object {
+      // Other Pigeon type tags describe other response objects.
+    }
+  }
+  throw StateError('Could not decode a platform product-details response');
+}
+
+/// A platform billing result that answers data getters through noSuchMethod.
+class PlatformBillingResultStub implements PlatformBillingResult {
+  /// Creates a billing result reporting [responseCode], [debugMessage], and
+  /// the default sub-response code of 0.
+  PlatformBillingResultStub(
+    PlatformBillingResponse responseCode,
+    String debugMessage, {
+    int subResponseCode = 0,
+  }) : stubbedMembers = <Symbol, Object?>{
+         #responseCode: responseCode,
+         #debugMessage: debugMessage,
+         #subResponseCode: subResponseCode,
+       };
+
+  /// The members this result answers, keyed by member name.
+  final Map<Symbol, Object?> stubbedMembers;
+
+  /// Supplies the positional data used by the Pigeon wire codec.
+  Object encode() {
+    return <Object?>[
+      stubbedMembers[#responseCode],
+      stubbedMembers[#debugMessage],
+      stubbedMembers[#subResponseCode],
+    ];
+  }
+
+  @override
+  dynamic noSuchMethod(Invocation invocation) {
+    if (invocation.isGetter &&
+        stubbedMembers.containsKey(invocation.memberName)) {
+      return stubbedMembers[invocation.memberName];
+    }
+    return super.noSuchMethod(invocation);
+  }
+}
+
+/// A platform product-details value whose one-time purchase offer list is
+/// supplied by the test, overriding the corresponding data getter so the test
+/// does not depend on the generated constructor name for that field.
+class PlatformProductDetailsStub extends PlatformProductDetails {
+  /// Creates a product-details value with the standard fields and the
+  /// [oneTimePurchaseOfferDetailsList] value to expose.
+  PlatformProductDetailsStub({
+    required String description,
+    required String name,
+    required String productId,
+    required PlatformProductType productType,
+    required String title,
+    required PlatformOneTimePurchaseOfferDetails? oneTimePurchaseOfferDetails,
+    required List<PlatformOneTimePurchaseOfferDetails>?
+    overriddenOneTimePurchaseOfferDetailsList,
+  }) : _oneTimePurchaseOfferDetailsList =
+           overriddenOneTimePurchaseOfferDetailsList,
+       super(
+         description: description,
+         name: name,
+         productId: productId,
+         productType: productType,
+         title: title,
+         oneTimePurchaseOfferDetails: oneTimePurchaseOfferDetails,
+       );
+
+  final List<PlatformOneTimePurchaseOfferDetails>?
+  _oneTimePurchaseOfferDetailsList;
+
+  @override
+  List<PlatformOneTimePurchaseOfferDetails>?
+  get oneTimePurchaseOfferDetailsList => _oneTimePurchaseOfferDetailsList;
+}
+
+/// Makes an opaque Pigeon value whose data exposes [productId]. The value is
+/// discovered through the generated message codec rather than by spelling or
+/// naming the implementation's platform element class.
+dynamic platformUnfetchedProductForTest(String productId) {
+  for (int typeTag = 128; typeTag <= 255; typeTag++) {
+    final WriteBuffer buffer = WriteBuffer();
+    buffer.putUint8(typeTag);
+    final dynamic codec = InAppPurchaseApi.pigeonChannelCodec;
+    codec.writeValue(buffer, <Object?>[productId]);
+    try {
+      final dynamic decoded = InAppPurchaseApi.pigeonChannelCodec.decodeMessage(
+        buffer.done(),
+      );
+      if (decoded.productId == productId) {
+        return decoded;
+      }
+    } on Object {
+      // A tag may belong to another Pigeon value or have a different shape.
+    }
+  }
+  // The base interface predates this value and does not decode it; it will
+  // fail the public response assertion without requiring a stand-in platform
+  // implementation.
+  return null;
+}
+
+/// Maps each of [names] to [value], so a stub can answer the same data under
+/// any of several member names.
+Map<Symbol, Object?> stubMemberAliases(Object? value, List<Symbol> names) {
+  return <Symbol, Object?>{for (final Symbol name in names) name: value};
+}
