+// Copyright 2013 The Flutter Authors
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+import 'package:flutter_test/flutter_test.dart';
+import 'package:in_app_purchase_android/billing_client_wrappers.dart';
+import 'package:in_app_purchase_android/src/messages.g.dart';
+import 'package:mockito/mockito.dart';
+
+import 'test_platform_response_builders.dart';
+import 'billing_client_wrappers/billing_client_wrapper_test.mocks.dart';
+
+void main() {
+  TestWidgetsFlutterBinding.ensureInitialized();
+
+  late MockInAppPurchaseApi mockApi;
+  late BillingClient billingClient;
+
+  setUp(() {
+    mockApi = MockInAppPurchaseApi();
+    when(mockApi.startConnection(any, any, any)).thenAnswer(
+      (_) async => PlatformBillingResultStub(PlatformBillingResponse.ok, ''),
+    );
+    billingClient = BillingClient(
+      (PurchasesResultWrapper _) {},
+      (UserChoiceDetailsWrapper _) {},
+      api: mockApi,
+    );
+  });
+
+  test('queryProductDetails preserves every distinct unfetched product ID', () async {
+    const List<String> ids = <String>['unfetched-first', 'unfetched-second'];
+    when(mockApi.queryProductDetailsAsync(any)).thenAnswer(
+      (_) async => platformResponseForTest(
+        responseCode: PlatformBillingResponse.ok,
+        unfetchedProducts: ids.map(platformUnfetchedProductForTest).toList(),
+      ),
+    );
+
+    final ProductDetailsResponseWrapper response = await billingClient
+        .queryProductDetails(
+          productList: ids
+              .map(
+                (String id) =>
+                    ProductWrapper(productId: id, productType: ProductType.inapp),
+              )
+              .toList(),
+        );
+    try {
+      final List<dynamic> unfetched =
+          (response as dynamic).unfetchedProductList as List<dynamic>;
+      expect(
+        unfetched.map((dynamic product) => product.productId as String).toList(),
+        ids,
+      );
+    } on NoSuchMethodError {
+      fail('The response must expose each unfetched product ID.');
+    }
+  });
+}

