@@ -0,0 +1,2736 @@
+import 'dart:io';
+
+import 'package:analyzer/dart/analysis/utilities.dart' as dart_ast_util;
+import 'package:analyzer/dart/ast/ast.dart' as dart_ast;
+import 'package:analyzer/dart/ast/visitor.dart' as dart_ast_visitor;
+import 'package:pigeon/src/pigeon_lib.dart';
+import 'package:test/test.dart';
+
+// These tests verify the observable contract for top-level constants: every
+// requested target output must expose a constant with an equivalent name and
+// the same value, written in a form the target-language toolchain accepts.
+// Rather than matching literal text in the generated source, each test
+// interprets the generated declarations with a target-appropriate reader:
+// the Dart analyzer for Dart output, `javac` plus a constant-field reader
+// for Java output, a C++ compiler plus a declaration reader for the C++
+// and GObject outputs, and semantics-preserving declaration readers
+// based on each language's literal grammar for the Kotlin, Swift, and
+// Objective-C outputs, whose toolchains are not normally present on
+// the test machine. Whitespace, quoting style, numeric suffixes,
+// visibility modifiers, string literal prefixes, declaration types,
+// naming conventions, and header/source placement are all intentionally
+// accepted.
+// ignore_for_file: use_raw_strings
+
+/// The backslash character, used to build test inputs without raw-string
+/// escaping pitfalls.
+const String _backslash = '\\';
+final String _dollar = String.fromCharCode(36);
+final String _newline = String.fromCharCode(10);
+
+/// A named constant with the value it must expose, identified by the name
+/// it is declared with in the Pigeon input.
+typedef _ExpectedConstant = ({String name, Object value});
+
+/// Builds a Pigeon input declaring a string constant whose value contains
+/// the given logical characters. [logical] must already be valid as the
+/// body of a single-quoted, escaped Dart string literal.
+String _stringConstInput(String name, String escapedBody) {
+  return "const String $name = '$escapedBody';$_newline";
+}
+
+/// Whether [actual], a name read from generated target code, is an
+/// equivalent spelling of the constant declared as [declared] in the
+/// Pigeon input: the same words in any identifier casing or punctuation
+/// convention, optionally preceded by one of the requested target-specific
+/// prefixes (the Objective-C `--objc_prefix FLT` or the GObject
+/// `--package_name test_package`) applied in any of the same conventions.
+/// Because the target language-and any prefixing option-may apply its own
+/// naming convention, equivalence is derived from the requested prefixing
+/// and case conversion rather than a closed list of concrete spellings.
+bool _isEquivalentConstantName(String declared, String actual) {
+  String normalize(String text) => text.toLowerCase().replaceAll(RegExp('[^a-z0-9]'), '');
+  final String remaining = normalize(actual);
+  final String wanted = normalize(declared);
+  if (remaining == wanted) {
+    return true;
+  }
+  // Each configured prefix option may be applied at most once, in any
+  // casing or punctuation convention. Some language conventions add a
+  // one-letter namespace as well (for example Objective-C `kFLTName`).
+  for (final String prefix in const <String>['flt', 'testpackage']) {
+    if (remaining.startsWith(prefix) &&
+        remaining.length > prefix.length &&
+        remaining.substring(prefix.length) == wanted) {
+      return true;
+    }
+    if (remaining.length > prefix.length + 1 &&
+        RegExp('[a-z]').hasMatch(remaining[0]) &&
+        remaining.substring(1).startsWith(prefix) &&
+        remaining.substring(prefix.length + 1) == wanted) {
+      return true;
+    }
+  }
+  // A generator may additionally apply a one character case namespace
+  // to the leading word; for example `k<Name>` in C++.
+  if (remaining.length > 1 &&
+      remaining.substring(1) == wanted &&
+      RegExp('[a-z]').hasMatch(remaining[0])) {
+    return true;
+  }
+  return false;
+}
+
+/// Whether [actual], read from generated target code, represents the same
+/// value as the Dart [expected] value. Integer constants may surface as
+/// wider types or with a floating point suffix in some targets, and are
+/// compared numerically.
+bool _valuesEqual(Object actual, Object expected) {
+  if (expected is String || expected is bool) {
+    return actual == expected;
+  }
+  if (expected is int) {
+    return actual == expected || (actual is double && actual == expected.toDouble());
+  }
+  if (expected is double) {
+    return actual is num && actual == expected;
+  }
+  return false;
+}
