+/// A human-readable description of [value] for failure messages that does
+/// not depend on embedding the value in a string literal.
+String _describe(Object value) {
+  if (value is String) {
+    return 'the ${value.length}-character string with code units '
+        '${value.codeUnits.map((int u) => 'U+${u.toRadixString(16).padLeft(4, '0')}').join(' ')}';
+  }
+  return '$value';
+}
+
+/// Returns the conventional boolean literal spelling of [value] for the
+/// given output kind, falling back to the lowercase spelling elsewhere.
+String _boolLiteralFor(String output, {required bool value}) {
+  switch (output) {
+    case 'gobject':
+      return value ? 'TRUE' : 'FALSE';
+    case 'objc':
+      return value ? 'YES' : 'NO';
+    default:
+      return value ? 'true' : 'false';
+  }
+}
+
+/// Creates a temporary directory for generated files.
