+  final String dartOut = '${tempDir.path}/messages.g.dart';
+  final String javaOut = '${tempDir.path}/Messages.java';
+  final String kotlinOut = '${tempDir.path}/messages.g.kt';
+  final String swiftOut = '${tempDir.path}/messages.g.swift';
+  final String objcHeaderOut = '${tempDir.path}/messages.g.h';
+  final String objcSourceOut = '${tempDir.path}/messages.g.m';
+  final String cppHeaderOut = '${tempDir.path}/messages.g.cpp.h';
+  final String cppSourceOut = '${tempDir.path}/messages.g.cpp';
+  final String gobjectHeaderOut = '${tempDir.path}/messages.g.gobject.h';
+  final String gobjectSourceOut = '${tempDir.path}/messages.g.gobject.cc';
+  final int exitCode = await Pigeon.run(<String>[
+    '--input',
+    inputPath,
+    '--dart_out',
+    dartOut,
+    '--java_out',
+    javaOut,
+    '--kotlin_out',
+    kotlinOut,
