+// ---------------------------------------------------------------------------
+// C-family source helpers (Objective-C, C++, GObject).
+// ---------------------------------------------------------------------------
+
+/// Returns a copy of [text] in which comments, string literals, and
+/// preprocessor directives are blanked out (newline characters preserved),
+/// so that token searches only see declaration syntax.
+String _codeOnly(String text) {
+  final List<String> chars = text.split('');
+  final int n = text.length;
+
+  void blankRange(int start, int end) {
+    for (int k = start; k < end && k < n; k++) {
+      if (chars[k] != _newline) {
+        chars[k] = ' ';
+      }
+    }
+  }
+
+  int i = 0;
+  while (i < n) {
+    final String c = text[i];
+    if (c == '"' || c == "'") {
+      // A character or string literal, optionally prefixed (`@"..."`,
+      // `u8"..."`). A closing quote is not recognized while an escaped
+      // parenthesis group is open, so a `\\(` format placeholder in an
+      // Objective-C format string cannot end the literal early.
+      final int start = i;
+      i++;
+      bool escaped = false;
+      int interpolated = 0;
+      while (i < n) {
+        final String s = text[i];
+        if (escaped) {
+          escaped = false;
+        } else if (interpolated > 0) {
+          if (s == _backslash) {
+            i++;
+          } else if (s == '(') {
+            interpolated++;
+          } else if (s == ')') {
+            interpolated--;
+          }
+        } else if (s == _backslash && i + 1 < n && text[i + 1] == '(') {
+          interpolated = 1;
+          i++;
+        } else if (s == _backslash) {
+          escaped = true;
+        } else if (s == c) {
+          i++;
+          break;
+        }
+        i++;
+      }
+      blankRange(start, i);
+    } else if (c == '/' && i + 1 < n && text[i + 1] == '/') {
+      final int end = text.indexOf(_newline, i);
+      final int stop = end < 0 ? n : end;
+      blankRange(i, stop);
+      i = stop;
+    } else if (c == '/' && i + 1 < n && text[i + 1] == '*') {
+      final int end = text.indexOf('*/', i + 2);
+      final int stop = end < 0 ? n : end + 2;
+      blankRange(i, stop);
+      i = stop;
+    } else if (c == '#') {
+      // A preprocessor directive reaches the end of its logical line.
+      int end = i;
+      while (end < n) {
+        final int nl = text.indexOf(_newline, end);
+        if (nl < 0) {
+          end = n;
+          break;
+        }
+        if (text[nl - 1] == _backslash) {
+          end = nl + 1;
+        } else {
+          end = nl;
+          break;
+        }
+      }
+      blankRange(i, end);
+      i = end;
+    } else {
+      i++;
+    }
+  }
+  return chars.join();
+}
+
+/// Interprets the C-style string literal beginning at offset [start] in
+/// [text] (which must point at a quote character) and returns the decoded
+/// contents together with the offset just past the closing quote.
+({String value, int end}) _readCString(String text, int start) {
+  final String quote = text[start];
+  int i = start + 1;
+  final StringBuffer buffer = StringBuffer();
+  bool escaped = false;
+  while (i < text.length) {
+    final String c = text[i];
+    // An Objective-C `\\(` string-format placeholder is not an escape
+    // sequence: the backslash escapes the parenthesis, which this reader
+    // correctly retains.
+    if (escaped && c == '(') {
+      buffer.write(c);
+      escaped = false;
+      i++;
+      continue;
+    }
+    if (escaped) {
+      escaped = false;
+      switch (c) {
+        case 'n':
+          buffer.write(_newline);
+        case 't':
+          buffer.write('\t');
+        case 'r':
+          buffer.write('\r');
+        case '0':
+          buffer.write(String.fromCharCode(0));
+        case 'x':
+          i++;
+          final StringBuffer hex = StringBuffer();
+          while (i < text.length && hex.length < 2 && RegExp('[0-9a-fA-F]').hasMatch(text[i])) {
+            hex.write(text[i]);
+            i++;
+          }
+          buffer.write(String.fromCharCode(int.parse(hex.toString(), radix: 16)));
+          continue;
+        case 'u':
+          i++;
+          if (i < text.length && text[i] == '{') {
+            final int close = text.indexOf('}', i);
+            buffer.write(String.fromCharCode(int.parse(text.substring(i + 1, close), radix: 16)));
+            i = close + 1;
+          } else {
+            buffer.write(String.fromCharCode(int.parse(text.substring(i, i + 4), radix: 16)));
+            i += 4;
+          }
+          continue;
+        case '\n':
+          i++;
+          continue;
+        default:
+          buffer.write(c);
+      }
+      i++;
+    } else if (c == _backslash) {
+      escaped = true;
+      i++;
+    } else if (c == quote) {
+      return (value: buffer.toString(), end: i + 1);
+    } else {
+      buffer.write(c);
+      i++;
+    }
+  }
+  fail('Unterminated string literal in generated code: $text');
+}
+
+/// Starting near offset [start] in [text], reads one C-family string
+/// literal plus any adjacent (whitespace-separated) literals that
+/// follow, and returns their combined logical value with the offset just
+/// past the last one. C++ raw strings (`R"tag(...)tag"` and the
+/// encoding-prefixed forms `u8R"..."`, `LR"..."`, `uR"..."`, and
+/// `UR"..."`) contribute their unescaped contents; ordinary literals
+/// (possibly prefixed with `@`, `u8`, `u`, `U`, or `L`) are decoded with
+/// [_readCString]. Throws a [StateError] when no string literal begins
+/// at or after [start] on the same line.
+({String value, int end}) _readCQuotedChunk(String text, int start) {
+  final StringBuffer combined = StringBuffer();
+  int cursor = start;
+  bool any = false;
+  while (cursor < text.length) {
+    while (cursor < text.length &&
+        (text[cursor] == ' ' ||
+            text[cursor] == '\t' ||
+            text[cursor] == _newline ||
+            text[cursor] == '\r')) {
+      cursor++;
+    }
+    if (cursor >= text.length) {
+      break;
+    }
+    int literalAt = cursor;
+    bool rawAllowed = true;
+    if (text[literalAt] == '@') {
+      literalAt = _skipHorizontalSpace(text, literalAt + 1);
+    } else {
+      final Match? prefix = RegExp('(u8|u|U|L)').matchAsPrefix(text, literalAt);
+      if (prefix != null) {
+        final int afterPrefix = prefix.end;
+        if (afterPrefix < text.length &&
+            (text[afterPrefix] == '"' || text[afterPrefix] == "'" || text[afterPrefix] == 'R')) {
+          literalAt = afterPrefix;
+        }
+      }
+    }
+    if (literalAt >= text.length) {
+      break;
+    }
+    if (text[literalAt] == '"' || text[literalAt] == "'") {
+      final ({String value, int end}) read = _readCString(text, literalAt);
+      combined.write(read.value);
+      any = true;
+      cursor = read.end;
+      continue;
+    }
+    // A C++ raw string literal: `R"tag( ... )tag"`. Must not be preceded
+    // by an identifier character when taken as the full token start.
+    if (rawAllowed && text[literalAt] == 'R') {
+      int quoteAt = literalAt + 1;
+      // Only accept `R"` with no intervening space, as the grammar requires.
+      if (quoteAt < text.length &&
+          text[quoteAt] == '"' &&
+          (literalAt == 0 || !RegExp('[A-Za-z0-9_]').hasMatch(text[literalAt - 1]))) {
+        final String remainder = text.substring(quoteAt + 1);
+        final RegExpMatch? tagMatch = RegExp(r'^([^() \x5c]{0,16})[(]').firstMatch(remainder);
+        if (tagMatch != null) {
+          final String tag = tagMatch.group(1)!;
+          final int paren = quoteAt + 1 + tagMatch.end;
+          final String terminator = ')' + tag + '"';
+          final int close = text.indexOf(terminator, paren);
+          if (close >= 0) {
+            combined.write(text.substring(paren, close));
+            any = true;
+            cursor = close + terminator.length;
+            continue;
+          }
+        }
+      }
+    }
+    break;
+  }
+  if (!any) {
+    throw StateError('expected a string literal at offset $start');
+  }
+  return (value: combined.toString(), end: cursor);
+}
+
+/// Returns the first offset at or after [index] that is not a space or
+/// tab.
+int _skipHorizontalSpace(String text, int index) {
+  int at = index;
+  while (at < text.length && (text[at] == ' ' || text[at] == '\t')) {
+    at++;
+  }
+  return at;
+}
+
+/// Blanks the body of C++ raw string literals (`R"tag(...)tag"`, or with
+/// the encodable prefixes `u8`, `u`, `U`, `L`), which the quote scanner
+/// cannot delimit because raw strings permit unescaped quotes. Their
+/// values are still read separately from the original text by
+/// [_readCQuotedChunk]. A raw literal is recognized only where one can
+/// begin: the `R` must not directly continue an identifier, except as
+/// the last character of an encodable literal prefix.
+String _blankRawLiterals(String text) {
+  final List<String> chars = text.split('');
+  int i = 0;
+  while (i < text.length - 2) {
+    if (text[i] != 'R' || text[i + 1] != '"') {
+      i++;
+      continue;
+    }
+    // The `R` must not follow an identifier character, unless it ends an
+    // encodable literal prefix (`u8R`, `uR`, `UR`, `LR`).
+    if (i > 0 && RegExp('[A-Za-z0-9_]').hasMatch(text[i - 1])) {
+      final String before = text.substring(0, i);
+      final bool prefixed =
+          (before.endsWith('u8') &&
+              (before.length == 2 ||
+                  !RegExp('[A-Za-z0-9_]').hasMatch(before[before.length - 3]))) ||
+          ((before.endsWith('u') || before.endsWith('U') || before.endsWith('L')) &&
+              (before.length == 1 || !RegExp('[A-Za-z0-9_]').hasMatch(before[before.length - 2])));
+      if (!prefixed) {
+        i++;
+        continue;
+      }
+    }
+    final int paren = text.indexOf('(', i);
+    if (paren < 0 || paren - (i + 2) > 16) {
+      i++;
+      continue;
+    }
+    final String tag = text.substring(i + 2, paren);
+    final int close = text.indexOf(')$tag"', paren + 1);
+    if (close < 0) {
+      i++;
+      continue;
+    }
+    for (int k = i; k < close + tag.length + 2; k++) {
+      if (chars[k] != _newline) {
+        chars[k] = ' ';
+      }
+    }
+    i = close + tag.length + 2;
+  }
+  return chars.join();
+}
+
+/// Reads the constants exposed by C-family sources, accepting both
+/// `<modifiers> <any declarator> <name> = <literal>;` declarations and
+/// plain `#define <name> <literal>` macros. The declarator words are not
+/// restricted to particular type spellings: a declaration is recognized
+/// whenever its head consists of declaration-shaped tokens (identifiers,
+/// `*`, and scope qualifiers) and the value is determined by the
+/// initializer form itself-quoted literals are strings, the target
+/// language's boolean spellings are booleans, and numeric literals are
+/// integers or doubles. Adjacent string literals are concatenated.
+/// Returns the exposed values keyed by name.
+Map<String, Object> _readCStyleConstants(String text) {
+  final Map<String, Object> values = <String, Object>{};
+  final String code = _codeOnly(_blankRawLiterals(text));
+  // `const`-style data declarations: for each `=` outside comments,
+  // strings, and preprocessor lines, collect the tokens back to the
+  // previous statement boundary, then classify the type tokens. The
+  // halves of comparison operators (`==`, `!=`, `<=`, `>=`) never start
+  // a declaration.
+  for (final RegExpMatch equals in RegExp('(?<![<>=!])=(?!=)').allMatches(code)) {
+    final int equalsAt = equals.start;
+    // Find the previous statement boundary.
+    int statementStart = 0;
+    for (int k = equalsAt - 1; k >= 0; k--) {
+      final String ch = code[k];
+      if (ch == ';' || ch == '{' || ch == '}') {
+        statementStart = k + 1;
+        break;
+      }
+    }
+    String head = code.substring(statementStart, equalsAt);
+    // A comma-separated declaration repeats the variable name but shares
+    // the type from its first declarator. Recover that type for later
+    // initializers so each generated value can be checked independently.
+    if (head.contains(',')) {
+      final int comma = head.lastIndexOf(',');
+      final String prior = head.substring(0, comma);
+      final int firstEquals = prior.indexOf('=');
+      if (firstEquals < 0) {
+        continue;
+      }
+      final String firstHead = prior.substring(0, firstEquals).trimRight();
+      final Match? firstName = RegExp(r'([A-Za-z_]\w*)\s*$').firstMatch(firstHead);
+      if (firstName == null) {
+        continue;
+      }
+      final String typeHead = firstHead.substring(0, firstName.start).trimRight();
+      head = '$typeHead ${head.substring(comma + 1).trim()}';
+    }
+    // Attribute spellings that may wrap a constant declaration (for
+    // example `FOUNDATION_EXPORT` in an Objective-C header or
+    // `G_GNUC_CONST` in a GObject header) are removed before the head is
+    // classified; their argument parenthesis becomes whitespace so a
+    // leftover `)` cannot merge with neighboring syntax.
+    head = head
+        .replaceAll(
+          RegExp('\\b(?:FOUNDATION_EXPORT|G_GNUC_CONST|G_GNUC_PURE|G_MODULE_EXPORT)\\b'),
+          ' ',
+        )
+        .replaceAll(RegExp('\\b__attribute__'), ' ')
+        .replaceAll(RegExp(r'<[^A-Za-z0-9_][^A-Za-z0-9_]*>'), ' ');
+    // The declaration head must consist only of identifiers, `*`,
+    // whitespace, and the scope resolution operator `::` used by
+    // qualified type names such as `std::string` (no parentheses,
+    // commas, or other operators).
+    if (head.contains(RegExp(r'[^A-Za-z0-9_*\s:\[\]]'))) {
+      continue;
+    }
+    // A single `:` on its own cannot appear in a plain type-and-name
+    // declaration head; only the paired `::` scope operator may.
+    final String unscoped = head.replaceAll('::', '');
+    if (unscoped.contains(':')) {
+      continue;
+    }
+    final List<RegExpMatch> tokens = RegExp(r'[A-Za-z_]\w*(?:\[\])?|\*').allMatches(head).toList();
+    if (tokens.length < 2) {
+      continue;
+    }
+    // The fragments of a scope qualifier are tokenized with the
+    // identifiers they join, so a scoped name such as `std::string`
+    // contributes both of its words to the type classification.
+    final String nameToken = tokens.last.group(0)!;
+    final bool hasBrackets = head.contains('[') || nameToken.endsWith('[]');
+    final String name = nameToken.endsWith('[]')
+        ? nameToken.substring(0, nameToken.length - 2)
+        : nameToken;
+    final Set<String> typeWords = tokens
+        .sublist(0, tokens.length - 1)
+        .map((RegExpMatch m) => m.group(0)!)
+        .toSet();
+    final bool hasStar = head.contains('*');
+    if (typeWords.contains(name)) {
+      // A repeated token means this is not a simple declaration.
+      continue;
+    }
+    int literalStart = equalsAt + 1;
+    while (literalStart < text.length &&
+        (text[literalStart] == ' ' ||
+            text[literalStart] == '\t' ||
+            text[literalStart] == _newline ||
+            text[literalStart] == '\r')) {
+      literalStart++;
+    }
+    // Read the literal from the ORIGINAL text after the `=`, past any
+    // literal prefix (`@`, `u8`, `u`, `U`, `L`) and any grouping
+    // parenthesis (Objective-C boxed expressions, GNU initializer
+    // parentheses).
+    while (literalStart < text.length) {
+      if (text[literalStart] == '(') {
+        int next = literalStart + 1;
+        while (next < text.length && (text[next] == ' ' || text[next] == '\t')) {
+          next++;
+        }
+        if (next >= text.length) {
+          break;
+        }
+        final String afterParen = text[next];
+        if (afterParen == '"' ||
+            afterParen == "'" ||
+            afterParen == '@' ||
+            afterParen == '-' ||
+            afterParen == '+' ||
+            RegExp('[0-9]').hasMatch(afterParen)) {
+          literalStart = next;
+          continue;
+        }
+        if (RegExp('[uUL]').hasMatch(afterParen) &&
+            next + 1 < text.length &&
+            (text[next + 1] == '"' ||
+                (next + 2 < text.length &&
+                    afterParen == 'u' &&
+                    text[next + 1] == '8' &&
+                    text[next + 2] == '"'))) {
+          continue;
+        }
+        break;
+      }
+      if (text[literalStart] == '@') {
+        int next = literalStart + 1;
+        while (next < text.length && (text[next] == ' ' || text[next] == '\t')) {
+          next++;
+        }
+        if (next < text.length &&
+            (text[next] == '"' ||
+                text[next] == "'" ||
+                text[next] == '(' ||
+                RegExp('[0-9.-]').hasMatch(text[next]))) {
+          literalStart = next;
+          continue;
+        }
+        break;
+      }
+      final Match? prefix = RegExp('(u8|u|U|L)').matchAsPrefix(text, literalStart);
+      if (prefix != null) {
+        int next = prefix.end;
+        while (next < text.length && (text[next] == ' ' || text[next] == '\t')) {
+          next++;
+        }
+        if (next < text.length && (text[next] == '"' || text[next] == "'" || text[next] == '@')) {
+          literalStart = next;
+          continue;
+        }
+      }
+      break;
+    }
+    while (literalStart < text.length &&
+        (text[literalStart] == ' ' ||
+            text[literalStart] == '\t' ||
+            text[literalStart] == _newline ||
+            text[literalStart] == '\r')) {
+      literalStart++;
+    }
+    final bool isStringPointer =
+        (hasStar || hasBrackets) &&
+        (typeWords.contains('char') ||
+            typeWords.contains('gchar') ||
+            typeWords.contains('gchararray'));
+    Object? value;
+    // Quoted initializers are string values, regardless of how the
+    // declaration spells its type. A pointer declarator may only carry a
+    // string (or a null pointer, which is not a constant value), so the
+    // initializer form alone determines the value for recognized targets.
+    if (typeWords.contains('NSString') ||
+        isStringPointer ||
+        (typeWords.contains('std') && typeWords.contains('string'))) {
+      try {
+        final ({String value, int end}) read = _readCQuotedChunk(text, literalStart);
+        value = read.value;
+      } on Object {
+        continue;
+      }
+    } else {
+      // The initializer form determines the value: a quoted literal is a
+      // string, a boolean spelling is a boolean, and a numeric literal is
+      // an integer or a double. No fixed set of type spellings is
+      // required, so any valid constant-bearing type idiom is read.
+      int scalarStart = literalStart;
+      while (scalarStart < text.length && text[scalarStart] == '(') {
+        scalarStart++;
+        while (scalarStart < text.length &&
+            (text[scalarStart] == ' ' || text[scalarStart] == '\t')) {
+          scalarStart++;
+        }
+      }
+      if (scalarStart < text.length && text[scalarStart] == '@') {
+        scalarStart += 1;
+        while (scalarStart < text.length &&
+            (text[scalarStart] == ' ' || text[scalarStart] == '\t')) {
+          scalarStart++;
+        }
+      }
+      if (scalarStart < text.length &&
+          (text[scalarStart] == '"' ||
+              text[scalarStart] == "'" ||
+              text[scalarStart] == 'R' ||
+              RegExp('^(u8|u|U|L)["\'R]').hasMatch(text.substring(scalarStart)))) {
+        try {
+          final ({String value, int end}) read = _readCQuotedChunk(text, scalarStart);
+          value = read.value;
+        } on Object {
+          continue;
+        }
+      } else {
+        final Match? glibInteger = RegExp(
+          r'G_GINT64_CONSTANT\s*\(\s*(-?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?)[fFlLuU]*\s*\)',
+        ).matchAsPrefix(text.substring(scalarStart));
+        if (glibInteger != null) {
+          final String raw = glibInteger.group(1)!;
+          value = raw.contains(RegExp(r'[.eE]')) ? double.parse(raw) : int.parse(raw);
+          if (value is int && typeWords.contains('double')) {
+            value = value.toDouble();
+          }
+        }
+        final Match? word = glibInteger == null
+            ? RegExp(r'[A-Za-z_]\w*').matchAsPrefix(code, scalarStart)
+            : null;
+        if (glibInteger != null) {
+          // The wrapper has already been interpreted above.
+        } else if (word != null &&
+            <String>{'true', 'TRUE', 'YES', 'false', 'FALSE', 'NO'}.contains(word.group(0))) {
+          value = word.group(0) == 'true' || word.group(0) == 'TRUE' || word.group(0) == 'YES';
+        } else {
+          final Match? numeric = RegExp(
+            '-?(?:\\d+\\.\\d*|\\.\\d+|\\d+)(?:[eE][+-]?\\d+)?[fFbBuUlL]*',
+          ).matchAsPrefix(text, scalarStart);
+          if (numeric == null) {
+            continue;
+          }
+          final String raw = numeric.group(0)!.replaceAll(RegExp(r'[fFbBuUlL]+$'), '');
+          final bool fractional =
+              numeric.group(0)!.toLowerCase().endsWith('f') || raw.contains(RegExp('[.eE]'));
+          value = fractional ? double.parse(raw) : int.parse(raw);
+          if (numeric.group(0)!.endsWith('b')) {
+            value = value != 0;
+          } else if (value is int && typeWords.contains('double')) {
+            value = value.toDouble();
+          }
+        }
+      }
+    }
+    if (value != null) {
+      values[name] = value;
+    }
+  }
+
+  // Third pass: an initializer written as a C++ raw string literal, or
+  // spread across adjacent literals, can join its `=`-separated head in
+  // the `code` view. Look for each declaration head immediately before
+  // a possible raw literal opener in the original text.
+  final RegExp rawOpener = RegExp('=(?![=>])[ \\t]*(?:u8|u|U|L)?R"');
+  for (final RegExpMatch opener in rawOpener.allMatches(text)) {
+    final int equalsAt = opener.start;
+    int statementStart = 0;
+    for (int k = equalsAt - 1; k >= 0; k--) {
+      final String ch = code[k];
+      if (ch == ';' || ch == '{' || ch == '}') {
+        statementStart = k + 1;
+        break;
+      }
+    }
+    final String head = code
+        .substring(statementStart, equalsAt)
+        .replaceAll(
+          RegExp('\\b(?:FOUNDATION_EXPORT|G_GNUC_CONST|G_GNUC_PURE|G_MODULE_EXPORT)\\b'),
+          ' ',
+        )
+        .replaceAll(RegExp('\\b__attribute__'), ' ')
+        .replaceAll(RegExp(r'<[^A-Za-z0-9_][^A-Za-z0-9_]*>'), ' ');
+    if (head.contains(RegExp(r'[^A-Za-z0-9_*\s:\[\]]')) ||
+        head.replaceAll('::', '').contains(':')) {
+      continue;
+    }
+    final List<RegExpMatch> tokens = RegExp(r'[A-Za-z_]\w*(?:\[\])?|\*').allMatches(head).toList();
+    if (tokens.length < 2) {
+      continue;
+    }
+    final String nameToken = tokens.last.group(0)!;
+    final String name = nameToken.endsWith('[]')
+        ? nameToken.substring(0, nameToken.length - 2)
+        : nameToken;
+    try {
+      final ({String value, int end}) read = _readCQuotedChunk(text, equalsAt + 1);
+      values.putIfAbsent(name, () => read.value);
+    } on Object {
+      continue;
+    }
+  }
+
+  // Plain `#define NAME <literal>` macros (GObject style).
+  for (final String line in text.split(_newline)) {
+    final String trimmed = line.trim();
+    if (!trimmed.startsWith('#define')) {
+      continue;
+    }
+    final String rest = trimmed.substring('#define'.length).trimLeft();
+    final RegExpMatch? nameMatch = RegExp(r'^[A-Za-z_]\w*').firstMatch(rest);
+    if (nameMatch == null) {
+      continue;
+    }
+    final String name = nameMatch.group(0)!;
+    // Skip function-like macro declarations.
+    if (rest.length > name.length && rest[name.length] == '(') {
+      continue;
+    }
+    final String literal = rest.substring(name.length).trim();
+    if (literal.isEmpty) {
+      continue;
+    }
+    if (literal.startsWith('@')) {
+      // Objective-C boxed literal (`@10`, `@2.5`, `@YES`) or string.
+      if (literal.startsWith('@"')) {
+        try {
+          final ({String value, int end}) read = _readCString(literal, 1);
+          values[name] = read.value;
+        } on Object {
+          // Not a well-formed string macro; ignore.
+        }
+        continue;
+      }
+      final RegExpMatch? boxed = RegExp('@(-?\\d+(\\.\\d+)?)').firstMatch(literal);
+      if (boxed != null) {
+        final String raw = boxed.group(1)!;
+        values[name] = raw.contains('.') ? double.parse(raw) : int.parse(raw);
+      } else if (literal.startsWith('@YES')) {
+        values[name] = true;
+      } else if (literal.startsWith('@NO')) {
+        values[name] = false;
+      }
+      continue;
+    }
+    if (literal.startsWith('"')) {
+      try {
+        final ({String value, int end}) read = _readCString(literal, 0);
+        values[name] = read.value;
+      } on Object {
+        // Not a well-formed string macro; ignore.
+      }
+      continue;
+    }
+    if (literal == 'TRUE' || literal == 'YES' || literal == 'true') {
+      values[name] = true;
+      continue;
+    }
+    if (literal == 'FALSE' || literal == 'NO' || literal == 'false') {
+      values[name] = false;
+      continue;
+    }
+    String number = literal.trim();
+    final RegExpMatch? glibInteger = RegExp(r'^G_GINT64_CONSTANT\s*\((.*)\)$').firstMatch(number);
+    if (glibInteger != null) {
+      number = glibInteger.group(1)!.trim();
+    }
+    while (number.startsWith('(') && number.endsWith(')')) {
+      number = number.substring(1, number.length - 1).trim();
+    }
+    final RegExpMatch? numeric = RegExp(
+      r'^-?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?[fFlLuU]*$',
+    ).firstMatch(number);
+    if (numeric != null) {
+      final String digits = number.replaceAll(RegExp(r'[fFlLuU]+$'), '');
+      values[name] = digits.contains(RegExp(r'[.eE]')) ? double.parse(digits) : int.parse(digits);
+    }
+  }
+  return values;
+}
