+/// Reads the value a C-family source exposes for the constant [name],
+/// under any conventional respelling, or null when none is recognized.
+Object? _readCStyleConstantValue(String source, String output, String name) {
+  final Map<String, Object> exposed = _readCStyleConstants(source);
+  for (final MapEntry<String, Object> entry in exposed.entries) {
+    if (_isEquivalentConstantName(name, entry.key)) {
+      if (output == 'gobject' && entry.value is int && (entry.value == 0 || entry.value == 1)) {
+        return entry.value == 1;
+      }
+      return entry.value;
+    }
+  }
+  return null;
+}
