+/// Asserts that the combined C-family sources [texts] (the header and
+/// its paired source for one target) expose every [expected] constant
+/// under any conventional respelling of its name, with the right value.
+/// A definition may appear in either file, or be declared `extern` in
+/// one file and defined in the other, because both are read together.
+void _expectCStyleConstants(String output, List<String> texts, List<_ExpectedConstant> expected) {
+  final String combined = texts.join(_newline);
+  final Map<String, Object> exposed = _readCStyleConstants(combined);
+  final List<String> problems = <String>[];
+  for (final _ExpectedConstant constant in expected) {
+    bool found = false;
+    for (final MapEntry<String, Object> entry in exposed.entries) {
+      final Object actual =
+          output == 'gobject' &&
+              constant.value is bool &&
+              entry.value is int &&
+              (entry.value == 0 || entry.value == 1)
+          ? entry.value == 1
+          : entry.value;
+      if (_isEquivalentConstantName(constant.name, entry.key) &&
+          _valuesEqual(actual, constant.value)) {
+        found = true;
+        break;
+      }
+    }
+    if (!found) {
+      problems.add('${constant.name} (expected ${_describe(constant.value)})');
+    }
+  }
+  expect(
+    problems,
+    isEmpty,
+    reason:
+        '$output output should expose the input constants as valid '
+        'declarations or macros; missing or mismatched: ${problems.join('; ')}',
+  );
+}
