+/// Reads an initialized var-style declaration whose initializer applies the
+/// unary `-` or `!` operators at most once to a simple literal with
+/// compile-time-constant semantics, or is a merely parenthesized literal.
+/// Returns the value, or null when the form is not recognized.
+Object? _readDesugaredVarLiteral(dart_ast.Expression expression) {
+  if (expression is dart_ast.ParenthesizedExpression) {
+    return _readDesugaredVarLiteral(expression.expression);
+  }
+  if (expression is dart_ast.PrefixExpression) {
+    final Object? operand = _readDesugaredVarLiteral(expression.operand);
+    final String op = expression.operator.lexeme;
+    if (op == '-') {
+      if (operand is int) {
+        return -operand;
+      }
+      if (operand is double) {
+        return -operand;
+      }
+      return null;
+    }
+    if (op == '!') {
+      return operand is bool ? !operand : null;
+    }
+    return null;
+  }
+  return _DartConstantReader.literalValue(expression);
+}
