+/// Reads the constant fields a generated Java [source] declares. The
+/// declaration head is not restricted to particular modifier or type
+/// spellings: any `... name = literal;` statement introduces a candidate
+/// field, provided the head contains no expression operators or call
+/// parentheses (so assignments inside method bodies are not mistaken for
+/// declarations).
+Map<String, Object> _readJavaConstantFields(String source) {
+  final Map<String, Object> fields = <String, Object>{};
+  final String statements = source
+      .replaceAll(RegExp(r'@[A-Za-z_][A-Za-z0-9_.]*(\([^)]*\))?[ \t]*'), ' ')
+      .replaceAll(RegExp('[ \t]*' + _newline + '[ \t]*'), ' ')
+      .replaceAll('  ', ' ');
+  for (final String statement in statements.split(';')) {
+    final RegExpMatch? declaration = RegExp(
+      r'(?:^|[^.\w])((?:[A-Za-z_]\w*[ \t]+)+|var[ \t]+)([A-Za-z_]\w*)[ \t]*=[ \t]*(.*?)$',
+    ).firstMatch(statement);
+    if (declaration == null) {
+      continue;
+    }
+    final String head = declaration.group(1)!;
+    final String name = declaration.group(2)!;
+    if (!head.startsWith('var') && head.contains(RegExp(r'[^A-Za-z0-9_. \t]'))) {
+      // Expression operators or call parentheses mean this is an
+      // assignment inside a statement, not a field declaration head.
+      continue;
+    }
+    final Object? value = _interpretJavaLiteral(declaration.group(3)!);
+    if (value != null) {
+      fields[name] = value;
+    }
+  }
+  return fields;
+}
+
+/// Reads the value the generated Java [source] exposes for the constant
+/// [name] under any equivalent naming convention, or null when no
+/// recognized declaration spells the value.
+Object? _readJavaConstantValue(String source, String name) {
+  for (final MapEntry<String, Object> entry in _readJavaConstantFields(source).entries) {
+    if (_isEquivalentConstantName(name, entry.key)) {
+      return entry.value;
+    }
+  }
+  return null;
+}
