+/// generated Java code, returning the classes directory to use as a
+/// classpath, or null if `javac` is unavailable on the test machine.
+Future<Directory?> _javaStubs(Directory scratch) async {
+  final Directory stubRoot = Directory('${scratch.path}${Platform.pathSeparator}java_stubs');
+  final Directory classes = Directory('${stubRoot.path}${Platform.pathSeparator}classes')
+    ..createSync(recursive: true);
