+/// Interprets [literal], a Java constant expression as it appears on the
+/// right-hand side of a generated constant field declaration, returning a
+/// String, int, double, or bool, or null when the expression is not a
+/// recognized literal. String literals may be adjacent concatenations.
+Object? _interpretJavaLiteral(String literal) {
+  final String text = literal.trim();
+  if (text.startsWith('(') && text.length > 2) {
+    // A parenthesized initialization such as `(100)` or `(true)`.
+    return _interpretJavaLiteral(text.substring(1, text.length - 1));
+  }
+  if (text.endsWith('.class') && text.length > '.class'.length) {
+    // A type-literal initialization such as `boolean.class`.
+    final String boxed = text.substring(0, text.length - '.class'.length);
+    if (boxed == 'boolean') {
+      return false;
+    }
+    if (boxed == 'Boolean') {
+      return true;
+    }
+    return null;
+  }
+  if (text.startsWith('"')) {
+    final StringBuffer buffer = StringBuffer();
+    final RegExp parts = RegExp(r'"((?:[^"\\]|\\.)*)"');
+    int consumed = 0;
+    for (final RegExpMatch part in parts.allMatches(text)) {
+      final String between = text.substring(consumed, part.start).trim();
+      if (between.isNotEmpty && between != '+') {
+        return null;
+      }
+      consumed = part.end;
+      buffer.write(_unquoteJavaString(part.group(1)!));
+    }
+    if (consumed == 0 || text.substring(consumed).trim().isNotEmpty) {
+      return null;
+    }
+    return buffer.toString();
+  }
+  if (text == 'true' || text == 'false') {
+    return text == 'true';
+  }
+  final RegExpMatch? integer = RegExp(
+    r'^(-?)(0[xX][0-9a-fA-F_]+|0[bB][01_]+|0[0-7_]*|[0-9][0-9_]*)(?:[Ll])?$',
+  ).firstMatch(text);
+  if (integer != null) {
+    final String sign = integer.group(1)!;
+    final String digits = integer.group(2)!.replaceAll('_', '');
+    final int radix = digits.startsWith(RegExp('0[xX]'))
+        ? 16
+        : digits.startsWith(RegExp('0[bB]'))
+        ? 2
+        : digits.length > 1 && digits.startsWith('0')
+        ? 8
+        : 10;
+    final String magnitude = radix == 16 || radix == 2 ? digits.substring(2) : digits;
+    final int value = int.parse(magnitude, radix: radix);
+    return sign == '-' ? -value : value;
+  }
+  final RegExpMatch? real = RegExp(
+    r'^(-?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?)[FfDd]?$',
+  ).firstMatch(text);
+  if (real != null && real.group(1)!.contains(RegExp(r'[.eE]|-'))) {
+    return double.tryParse(real.group(1)!);
+  }
+  return null;
+}
