+/// Decodes the escape sequences in the body of a Java (or Kotlin) string
+/// literal.
+String _unquoteJavaString(String body) {
+  final StringBuffer buffer = StringBuffer();
+  int i = 0;
+  while (i < body.length) {
+    final String c = body[i];
+    if (c != _backslash) {
+      buffer.write(c);
+      i++;
+      continue;
+    }
+    i++;
+    if (i >= body.length) {
+      break;
+    }
+    final String escape = body[i];
+    switch (escape) {
+      case 'n':
+        buffer.write(_newline);
+      case 't':
+        buffer.write('\t');
+      case 'r':
+        buffer.write('\r');
+      case 'b':
+        buffer.write('\b');
+      case 'f':
+        buffer.write('\f');
+      case 'u':
+        if (i + 4 < body.length) {
+          buffer.write(String.fromCharCode(int.parse(body.substring(i + 1, i + 5), radix: 16)));
+          i += 4;
+        }
+      default:
+        buffer.write(escape);
+    }
+    i++;
+  }
+  return buffer.toString();
+}
