+// ---------------------------------------------------------------------------
+// Kotlin and Swift: declaration scanning over each literal grammar.
+// ---------------------------------------------------------------------------
+
+/// Whether [hashes] `#` characters appear in [source] starting at [index].
+bool _hashesFollow(String source, int index, int hashes) {
+  for (int k = 0; k < hashes; k++) {
+    if (index + k >= source.length || source[index + k] != '#') {
+      return false;
+    }
+  }
+  return true;
+}
+
+/// Scans [source] forward from [index] until after the next literal
+/// closing quote followed by [hashes] trailing `#` markers.
+int _endOfHashedQuote(String source, int index, int hashes) {
+  int i = index;
+  while (i < source.length) {
+    if (source[i] == '"' && _hashesFollow(source, i + 1, hashes)) {
+      return i + 1 + hashes;
+    }
+    i++;
+  }
+  throw StateError('unterminated extended-delimiter string in generated code');
+}
+
+/// Decodes the escape sequences in [body], the characters between the
+/// delimiters of a Kotlin ([kotlin] true, [hashes] zero) or Swift
+/// ([kotlin] false) string literal, where [hashes] is the number of `#`
+/// characters in an extended Swift delimiter. With [hashes] zero the
+/// backslash is the escape marker; otherwise `\` followed by [hashes]
+/// hashes marks an escape. String interpolation raises a [StateError],
+/// because only plain literal values are recognized.
+String _decodeScriptStringBody(String body, {required bool kotlin, required int hashes}) {
+  final StringBuffer buffer = StringBuffer();
+  int i = 0;
+  while (i < body.length) {
+    final String c = body[i];
+    if (c != _backslash) {
+      buffer.write(c);
+      i++;
+      continue;
+    }
+    int j = i + 1;
+    int found = 0;
+    while (j < body.length && found < hashes && body[j] == '#') {
+      j++;
+      found++;
+    }
+    if (found != hashes || j >= body.length) {
+      buffer.write(c);
+      i++;
+      continue;
+    }
+    final String escape = body[j];
+    switch (escape) {
+      case 'n':
+        buffer.write(_newline);
+      case 't':
+        buffer.write('\t');
+      case 'r':
+        buffer.write('\r');
+      case 'b':
+        if (kotlin) {
+          buffer.write('\b');
+        } else {
+          buffer.write(escape);
+        }
+      case 'u':
+        if (j + 1 < body.length && body[j + 1] == '{') {
+          final int close = body.indexOf('}', j);
+          buffer.write(String.fromCharCode(int.parse(body.substring(j + 2, close), radix: 16)));
+          j = close;
+        } else if (kotlin && j + 4 < body.length) {
+          buffer.write(String.fromCharCode(int.parse(body.substring(j + 1, j + 5), radix: 16)));
+          j += 4;
+        } else {
+          buffer.write(escape);
+        }
+      case 'f':
+        // Neither Kotlin nor Swift defines a `\f` escape, so an active one
+        // in generated code is invalid source.
+        throw StateError('`\\f` is not a valid Kotlin or Swift escape');
+      case '(':
+        // String interpolation is not a literal value.
+        throw StateError('string interpolation in generated literal');
+      default:
+        buffer.write(escape);
+    }
+    i = j + 1;
+  }
+  return buffer.toString();
+}
+
+/// Returns the first offset at or after [index] that is not a space,
+/// tab, carriage return, or newline.
+int _skipSpacesAndNewlines(String source, int index) {
+  int at = index;
+  while (at < source.length &&
+      (source[at] == ' ' || source[at] == '\t' || source[at] == '\r' || source[at] == _newline)) {
+    at++;
+  }
+  return at;
+}
+
+/// Recognizes the Kotlin or Swift string literal expression beginning at
+/// offset [start] in [source] and returns its decoded logical value and
+/// the offset just past the end of the expression. Ordinary and
+/// triple-quoted Kotlin strings, adjacent `+`-concatenated Kotlin
+/// string literals, and extended-delimiter (`#...#"..."#...#`) Swift
+/// strings (single- and multiline) are accepted. Throws a [StateError]
+/// when no recognized plain string literal begins at [start]; string
+/// interpolation in particular is not a plain literal.
+({String value, int end}) _readScriptStringAt(String source, int start, {required bool kotlin}) {
+  int at = start;
+  int hashes = 0;
+  if (!kotlin) {
+    while (at < source.length && source[at] == '#') {
+      hashes++;
+      at++;
+    }
+  }
+  // Multiline (triple-quoted) forms.
+  if (at + 2 < source.length && source.startsWith('"""', at)) {
+    if (kotlin) {
+      final int close = source.indexOf('"""', at + 3);
+      if (close < 0) {
+        throw StateError('unterminated Kotlin raw string in generated code');
+      }
+      return (value: source.substring(at + 3, close), end: close + 3);
+    }
+    final String delimiter = '"""${'#' * hashes}';
+    final int close = source.indexOf(delimiter, at + 3);
+    if (close < 0) {
+      throw StateError('unterminated Swift multiline string in generated code');
+    }
+    return (
+      value: _decodeScriptStringBody(
+        source.substring(at + 3, close),
+        kotlin: false,
+        hashes: hashes,
+      ),
+      end: close + delimiter.length,
+    );
+  }
+  if (at >= source.length || (source[at] != '"' && !(kotlin && source[at] == "'"))) {
+    throw StateError('not a string literal at offset $start');
+  }
+  final String openerQuote = source[at];
+  final int bodyStart = at + 1;
+  int end;
+  if (hashes > 0) {
+    end = _endOfHashedQuote(source, bodyStart, hashes);
+  } else if (kotlin && openerQuote == "'") {
+    // A Kotlin char literal such as '\n' or '\u0041' is a one-character
+    // string in every sense the contract cares about.
+    final Match? single = RegExp(
+      "'(?:[^'" +
+          _backslash * 2 +
+          ']|' +
+          _backslash * 2 +
+          "u[0-9a-fA-F]{4}|" +
+          _backslash * 2 +
+          ".)'",
+    ).matchAsPrefix(source, at);
+    if (single == null) {
+      throw StateError('unterminated Kotlin char literal in generated code');
+    }
+    return (
+      value: _decodeScriptStringBody(
+        single.group(0)!.substring(1, single.group(0)!.length - 1),
+        kotlin: true,
+        hashes: 0,
+      ),
+      end: single.end,
+    );
+  } else {
+    final Match? plain = RegExp(
+      '"((?:[^"' + _backslash * 2 + ']|' + _backslash * 2 + '.)*)"',
+    ).matchAsPrefix(source, at);
+    if (plain == null) {
+      throw StateError('unterminated string literal in generated code');
+    }
+    end = plain.end;
+  }
+  int currentEnd = end;
+  final StringBuffer combined = StringBuffer(
+    _decodeScriptStringBody(
+      source.substring(bodyStart, currentEnd - 1 - hashes),
+      kotlin: kotlin,
+      hashes: hashes,
+    ),
+  );
+  // Kotlin permits `+`-concatenated adjacent string literals whose literal
+  // parts share one quoting convention.
+  if (kotlin) {
+    int cursor = _skipSpacesAndNewlines(source, currentEnd);
+    while (cursor < source.length && source[cursor] == '+') {
+      final int next = _skipSpacesAndNewlines(source, cursor + 1);
+      try {
+        final ({String value, int end}) part = _readScriptStringAt(source, next, kotlin: kotlin);
+        if (next < source.length && source[next] != openerQuote) {
+          // A part opened with a different delimiter is left to stricter
+          // readers; do not guess at a combined representation.
+          break;
+        }
+        combined.write(part.value);
+        cursor = _skipSpacesAndNewlines(source, part.end);
+        currentEnd = part.end;
+      } on Object {
+        break;
+      }
+    }
+  }
+  return (value: combined.toString(), end: currentEnd);
+}
+
+/// Recognizes a boolean or numeric literal at the very start of [rest]
+/// and returns its value and end offset within that substring. Throws a
+/// [StateError] when the text does not begin with a recognized plain
+/// scalar literal.
+({Object value, int end}) _readScalarLiteral(String rest, {required bool kotlin}) {
+  final RegExpMatch? boolean = RegExp('^(true|false)(?![A-Za-z0-9_])').firstMatch(rest);
+  if (boolean != null) {
+    return (value: boolean.group(1) == 'true', end: boolean.end);
+  }
+  // A Kotlin single-character literal in single quotes can spell the ASCII
+  // booleans when the language maps them onto chars; treat it as set or
+  // clear the same way the C-family math constants spell them.
+  if (kotlin && (rest.startsWith("'T'") || rest.startsWith("'t'"))) {
+    return (value: true, end: 3);
+  }
+  if (kotlin && (rest.startsWith("'F'") || rest.startsWith("'f'"))) {
+    return (value: false, end: 3);
+  }
+  final RegExpMatch? real = RegExp(
+    '^(-?(?:[0-9]+[.][0-9]+|[.][0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+[.][0-9]+[eE][+-]?[0-9]+))(f|F|d|D)?(?![A-Za-z0-9_.])',
+  ).firstMatch(rest);
+  if (real != null) {
+    return (value: double.parse(real.group(1)!), end: real.end);
+  }
+  final RegExp intPattern = kotlin
+      ? RegExp('^(-?[0-9]+)(?:[LlBb]|(u|U)[Ll]?)?(?![A-Za-z0-9_.])')
+      : RegExp('^(-?[0-9]+)(?![A-Za-z0-9_.])');
+  final RegExpMatch? integer = intPattern.firstMatch(rest);
+  if (integer != null) {
+    final int magnitude = int.parse(integer.group(1)!);
+    if (kotlin && rest.substring(0, integer.end).endsWith('B')) {
+      // A Byte literal can only spell a small value; it is a boolean when
+      // used as one, and otherwise the small value itself.
+      return (
+        value: magnitude == 0
+            ? false
+            : magnitude == 1
+            ? true
+            : magnitude,
+        end: integer.end,
+      );
+    }
+    return (value: magnitude, end: integer.end);
+  }
+  throw StateError('unrecognized literal in generated code');
+}
+
+/// Recognizes the Kotlin literal expression beginning at offset [start]
+/// in [source], returning its value and the offset just past the
+/// expression. The special-suffix numeric spellings (`0.5F`, `2L`),
+/// a single-character literal (`' '`, `'\n'`, `'\u0041'`), and a compact
+/// value-class initializer (`Boolean(true)`) are all plain values.
+({Object value, int end}) _readKotlinLiteralAt(String source, int start) {
+  if (start < source.length && source.startsWith('Boolean(', start)) {
+    final Match? call = RegExp('Boolean\\((true|false)\\)').matchAsPrefix(source, start);
+    if (call != null) {
+      return (value: call.group(1) == 'true', end: call.end);
+    }
+  }
+  if (start < source.length && (source[start] == '"' || source[start] == "'")) {
+    try {
+      return _readScriptStringAt(source, start, kotlin: true);
+    } on Object {
+      // Not a plain string literal; the scalar reader below will throw.
+    }
+  }
+  final ({Object value, int end}) read = _readScalarLiteral(source.substring(start), kotlin: true);
+  return (value: read.value, end: start + read.end);
+}
+
+/// Recognizes the Swift literal expression beginning at offset [start]
+/// in [source], returning its value and the offset just past the
+/// expression. In addition to the plain literal grammar, an explicitly
+/// typed scalar initializer (`Bool(true)`, `Int(2)`, `Double(2.5)`,
+/// `Float(2.5)`, or `String("...")`) is read as the same value.
+({Object value, int end}) _readSwiftLiteralAt(String source, int start) {
+  final Match? typedScalar = RegExp(
+    '(Bool|Int|Double|Float)\\((-?(?:[0-9]+(?:[.][0-9]+)?|true|false))\\)',
+  ).matchAsPrefix(source, start);
+  if (typedScalar != null) {
+    final String typeName = typedScalar.group(1)!;
+    final String raw = typedScalar.group(2)!;
+    if (raw == 'true' || raw == 'false') {
+      return (value: raw == 'true', end: typedScalar.end);
+    }
+    if (typeName == 'Int') {
+      return (value: int.parse(raw), end: typedScalar.end);
+    }
+    return (value: double.parse(raw), end: typedScalar.end);
+  }
+  final Match? typedString = RegExp('String\\(').matchAsPrefix(source, start);
+  if (typedString != null) {
+    try {
+      final ({String value, int end}) inner = _readScriptStringAt(
+        source,
+        typedString.end,
+        kotlin: false,
+      );
+      if (inner.end < source.length && source[inner.end] == ')') {
+        return (value: inner.value, end: inner.end + 1);
+      }
+    } on Object {
+      // Fall through to the ordinary readers.
+    }
+  }
+  if (start < source.length && (source[start] == '"' || source[start] == '#')) {
+    try {
+      return _readScriptStringAt(source, start, kotlin: false);
+    } on Object {
+      // Not a plain string literal; the scalar reader below will throw.
+    }
+  }
+  final ({Object value, int end}) read = _readScalarLiteral(source.substring(start), kotlin: false);
+  return (value: read.value, end: start + read.end);
+}
+
+/// Scans script-style generated code (Kotlin or Swift) for initialized
+/// constant declarations and asserts that it exposes every expected
+/// constant. Two mechanisms are supported, matching the two ways the
+/// contract's "valid source in the target language" requirement can be
+/// discharged:
+///
+/// * For Kotlin, an `object` name declaration may pair `val` fields inside
+///   the object with `val` or `fun` accessors of the same name elsewhere;
+///   both the field and an accessor initialized by a recognized literal
+///   expression are read directly.
+/// * For both languages, an initialized `val`/`var` (Kotlin) or
+///   `static let`/`static var`/`let`/`var` (Swift) declaration whose
+///   initializer is a recognized literal expression is read directly.
+///
+/// Whitespace, naming, visibility, annotation, and quoting style are
+/// all intentionally left unconstrained.
+class _ScriptConstantExpectation {
+  _ScriptConstantExpectation(
+    this.output,
+    this.source,
+    this.keywords,
+    this.readLiteralAt,
+    this.isKotlin,
+  );
+
+  /// The output kind, used for error messages and name respellings.
+  final String output;
+
+  /// The generated single-file source to inspect.
+  final String source;
+
+  /// The declaration keywords that introduce a constant declaration.
+  final Set<String> keywords;
+
+  /// Reads the literal expression beginning at a source offset.
+  final ({Object value, int end}) Function(String source, int start) readLiteralAt;
+
+  /// Whether the source follows the Kotlin grammar.
+  final bool isKotlin;
+
+  /// The recognized literal constant declarations, keyed by exposed name.
+  final Map<String, Object> _exposed = <String, Object>{};
+
+  /// Pending `fun name() = <expression>` bodies awaiting resolution after
+  /// the whole file has been scanned, keyed by accessor name.
+  final Map<String, int> _deferredFunctions = <String, int>{};
+
+  /// Runs the scan and records the recognized declarations.
+  void scan() {
+    final String inner = keywords.join('|');
+    final RegExp declaration = RegExp(
+      '(?:^|[{;}' +
+          _newline +
+          '])'
+              '((?:[^' +
+          _newline +
+          '=<>!]*[ \t])?)'
+              '(?:' +
+          inner +
+          ')[ \t]+([A-Za-z_]\\w*)[ \t]*([^=;{}' +
+          _newline +
+          ']*)=(?!=[=>])',
+    );
+    for (final RegExpMatch match in declaration.allMatches(source)) {
+      // The optional modifier run must consist of recognized modifier or
+      // annotation words only, so that keywords embedded in ordinary code
+      // (such as an identifier ending in `val` or a statement spanning a
+      // line) cannot start a false declaration.
+      final String modifiers = match.group(1) ?? '';
+      final bool modifiersOk = modifiers
+          .trim()
+          .split(RegExp('[ \t]+'))
+          .where((String token) => token.isNotEmpty)
+          .every(
+            (String token) =>
+                token.startsWith('@') ||
+                <String>{
+                  'public',
+                  'private',
+                  'internal',
+                  'fileprivate',
+                  'protected',
+                  'open',
+                  'static',
+                  'final',
+                  'const',
+                  'data',
+                  'inline',
+                  'override',
+                  'lateinit',
+                  'lazy',
+                  'external',
+                }.contains(token),
+          );
+      if (!modifiersOk) {
+        continue;
+      }
+      final String name = match.group(2)!;
+      final String tail = match.group(3)!.trimLeft();
+      // After the name only a type annotation may intervene before `=`.
+      if (tail.isNotEmpty && !tail.startsWith(':')) {
+        continue;
+      }
+      final int valueStart = _skipSpacesAndNewlines(source, match.end);
+      try {
+        final ({Object value, int end}) read = readLiteralAt(source, valueStart);
+        _exposed[name] = read.value;
+      } on Object {
+        // Not a recognized bounded plain literal; try a Kotlin
+        // object-instance reference.
+        if (isKotlin) {
+          final Object? chained = _readKotlinChainedReference(name, valueStart);
+          if (chained != null) {
+            _exposed[name] = chained;
+          }
+        }
+        continue;
+      }
+    }
+    if (isKotlin) {
+      _scanKotlinShortFunctions();
+      _scanKotlinObjectFields();
+    }
+  }
+
+  /// Reads `ClassName.property` at [valueStart] when the property has the
+  /// same name as the declaration it initializes and the class declares a
+  /// literal field of that name. Returns the field value, or null.
+  Object? _readKotlinChainedReference(String name, int valueStart) {
+    final Match? reference = RegExp(
+      '([A-Za-z_]\\w*)[.]([A-Za-z_]\\w*)',
+    ).matchAsPrefix(source, valueStart);
+    if (reference == null || reference.group(2)! != name) {
+      return null;
+    }
+    final String className = reference.group(1)!;
+    final RegExp field = RegExp(
+      'class[ \t]+' +
+          RegExp.escape(className) +
+          r'[^{]*\{[^}]*' +
+          '(?:val|var)[ \t]+' +
+          RegExp.escape(name) +
+          '[^=]*=(?!=[=>])',
+      dotAll: true,
+    );
+    final Match? fieldMatch = field.firstMatch(source);
+    if (fieldMatch == null) {
+      return null;
+    }
+    final int fieldValueStart = _skipSpacesAndNewlines(source, fieldMatch.end);
+    try {
+      final ({Object value, int end}) read = readLiteralAt(source, fieldValueStart);
+      return read.value;
+    } on Object {
+      return null;
+    }
+  }
+
+  /// Scans for Kotlin short-form functions (`fun name() = <literal>`),
+  /// which are a valid Kotlin exposition of a constant.
+  void _scanKotlinShortFunctions() {
+    final RegExp function = RegExp(
+      '(?:^|[;{}' +
+          _newline +
+          '])'
+              r'[ \t]*fun[ \t]+(?:[A-Za-z_]\w*[.])?([A-Za-z_]\w*)[ \t]*\(\)[ \t]*=[ \t]*',
+    );
+    for (final RegExpMatch match in function.allMatches(source)) {
+      _deferredFunctions[match.group(1)!] = match.end;
+    }
+  }
+
+  /// Resolves the pending function bodies and object-instance references.
+  void _scanKotlinObjectFields() {
+    for (final MapEntry<String, int> entry in _deferredFunctions.entries) {
+      final String accessor = entry.key;
+      try {
+        final ({Object value, int end}) read = readLiteralAt(source, entry.value);
+        _exposed.putIfAbsent(accessor, () => read.value);
+        continue;
+      } on Object {
+        // Not a literal body; try an object-instance reference.
+      }
+      final Match? reference = RegExp(
+        '([A-Za-z_]\\w*)[.]([A-Za-z_]\\w*)',
+      ).matchAsPrefix(source, entry.value);
+      if (reference == null || reference.group(2)! != accessor) {
+        continue;
+      }
+      final String objectName = reference.group(1)!;
+      final RegExp objectField = RegExp(
+        'object[ \t]+' + RegExp.escape(objectName) + r'[^{]*\{([^}]*)\}',
+        dotAll: true,
+      );
+      final Match? objectMatch = objectField.firstMatch(source);
+      if (objectMatch == null) {
+        continue;
+      }
+      // Inside the object body, the field is declared with a `val` or
+      // `var` keyword; its literal initializer provides the value.
+      final String body = objectMatch.group(1)!;
+      final RegExp field = RegExp(
+        '(?:val|var)[ \t]+' + RegExp.escape(accessor) + '[^=;{}' + _newline + ']*=(?!=[=>])',
+      );
+      final Match? fieldMatch = field.firstMatch(body);
+      if (fieldMatch == null) {
+        continue;
+      }
+      final int bodyStart = objectMatch.start + objectMatch.group(0)!.indexOf('{') + 1;
+      final int valueStart = _skipSpacesAndNewlines(source, bodyStart + fieldMatch.end);
+      try {
+        final ({Object value, int end}) read = readLiteralAt(source, valueStart);
+        _exposed.putIfAbsent(accessor, () => read.value);
+      } on Object {
+        continue;
+      }
+    }
+  }
+
+  /// The recognized constant declarations, keyed by exposed name.
+  Map<String, Object> get exposed => _exposed;
+
+  /// Asserts that every [expected] constant was recognized with the right
+  /// value.
+  void verify(List<_ExpectedConstant> expected) {
+    final List<String> problems = <String>[];
+    for (final _ExpectedConstant constant in expected) {
+      bool found = false;
+      for (final MapEntry<String, Object> entry in _exposed.entries) {
+        if (_isEquivalentConstantName(constant.name, entry.key) &&
+            _valuesEqual(entry.value, constant.value)) {
+          found = true;
+          break;
+        }
+      }
+      if (!found) {
+        problems.add('${constant.name} (expected ${_describe(constant.value)})');
+      }
+    }
+    expect(
+      problems,
+      isEmpty,
+      reason:
+          'The generated $output output should expose the input constants '
+          'as initialized declarations; missing or mismatched: ${problems.join('; ')}',
+    );
+  }
+}
+
+/// Reads the value a Kotlin or Swift generated [source] exposes for the
+/// constant [name] under any conventional respelling, or null when no
+/// recognized declaration spells the value.
+Object? _readScriptConstantValue(String source, String output, String name) {
+  final bool isKotlin = output == 'kotlin';
+  final _ScriptConstantExpectation scan = _ScriptConstantExpectation(
+    output,
+    source,
+    isKotlin ? <String>{'val', 'var'} : <String>{'let', 'var', 'final'},
+    isKotlin ? _readKotlinLiteralAt : _readSwiftLiteralAt,
+    isKotlin,
+  );
+  scan.scan();
+  for (final MapEntry<String, Object> entry in scan.exposed.entries) {
+    if (_isEquivalentConstantName(name, entry.key)) {
+      return entry.value;
+    }
+  }
+  return null;
+}
+
+/// Asserts that the Kotlin or Swift generated [source] exposes every
+/// [expected] constant as an initialized declaration (`val` or `var` in
+/// Kotlin, `let` or `var` or `final` in Swift) whose literal value
+/// matches, regardless of modifiers, type annotations, declaration
+/// placement, or quoted literal form.
+void _expectScriptConstants(
+  String output,
+  String source,
+  List<_ExpectedConstant> expected,
+  Set<String> keywords,
+  ({Object value, int end}) Function(String source, int start) readLiteralAt,
+) {
+  final _ScriptConstantExpectation scan = _ScriptConstantExpectation(
+    output,
+    source,
+    keywords,
+    readLiteralAt,
+    keywords.contains('val'),
+  );
+  scan.scan();
+  scan.verify(expected);
+}
