+/// The first executable from [candidates] found on the PATH, or null.
+Future<String?> _firstAvailable(List<String> candidates) async {
+  for (final String candidate in candidates) {
+    try {
+      final ProcessResult probe = await Process.run(candidate, <String>['--version']);
+      if (probe.exitCode == 0) {
+        return candidate;
+      }
+    } on ProcessException {
+      // Not available.
+    }
+  }
+  return null;
+}
+
+/// Writes the C-family stub headers into [scratch] and runs a C++ syntax
+/// check of each generated [source] file. The test fails if no C++
+/// compiler is available or if the compiler rejects one of the files.
+Future<void> _expectCppSyntax(List<File> sources, Directory scratch) async {
+  final String id = sources
+      .map((File file) => file.uri.pathSegments.last.replaceAll(RegExp('[^A-Za-z0-9]'), '_'))
+      .join('_');
+  final Directory stubRoot = Directory('${scratch.path}${Platform.pathSeparator}c_stubs_$id');
+  for (final MapEntry<String, String> entry in _cStubHeaders.entries) {
+    final File header = File(
+      '${stubRoot.path}${Platform.pathSeparator}${entry.key.replaceAll('/', Platform.pathSeparator)}',
+    );
+    header.parent.createSync(recursive: true);
+    header.writeAsStringSync(entry.value);
+  }
+  final String? compiler = await _firstAvailable(<String>['g++', 'c++', 'clang++']);
+  expect(compiler, isNotNull, reason: 'A C++ compiler is required to check the generated C output');
+  for (final File source in sources) {
+    final ProcessResult result = await Process.run(compiler!, <String>[
+      '-x',
+      'c++',
+      '-fsyntax-only',
+      '-I${stubRoot.path}',
+      source.path,
+    ]);
+    expect(
+      result.exitCode,
+      0,
+      reason: 'The generated output must pass a C++ syntax check: ${result.stderr}',
+    );
+  }
+}
