+    });
+
+    test('constant values must match the declared type', () async {
+      await expectGenerationFails('const String myConst = 42;');
+    });
+
+    test('constant values must be literals, not arbitrary expressions', () async {
+      await expectGenerationFails('const int myConst = 1 + 2;');
+    });
+
+    test('string interpolation is not supported in constants', () async {
+      await expectGenerationFails(interpolated);
+    });
+
+    test('all unsupported constant declarations are rejected', () async {
+      // Constants without an explicit type annotation must be rejected.
+      await expectGenerationFails('const myConst = 42;');
+      // Unsupported constant types must be rejected.
+      await expectGenerationFails('const List<int> myConst = <int>[42];');
+      // Values that are not literals of the declared type must be rejected.
+      await expectGenerationFails('const String myConst = 42;');
+      await expectGenerationFails('const int myConst = 1 + 2;');
+      await expectGenerationFails(interpolated);
+    });
+  });
+}
+
+/// Reads constant-valued top-level variable declarations from parsed Dart
+/// source. A `const` or `final` declaration initialized by a literal
+/// expression provides compile-time-constant semantics directly; an
+/// explicitly typed non-final `var` declaration is accepted only with a
+/// plain-literal initializer (optionally parenthesized), which is the
+/// only assignable form whose value cannot change through a later
+/// expression while still spelling the value in the source.
+class _DartConstantReader extends dart_ast_visitor.RecursiveAstVisitor<void> {
+  final Map<String, Object> values = <String, Object>{};
+
+  /// Parses [source] and returns the constant-valued top-level variables
+  /// it declares. Parse errors yield an empty map.
+  static Map<String, Object> readTopLevelConstants(String source) {
+    final dynamic parsed = dart_ast_util.parseString(content: source, throwIfDiagnostics: false);
+    final _DartConstantReader reader = _DartConstantReader();
+    (parsed.unit as dart_ast.CompilationUnit).visitChildren(reader);
+    return reader.values;
+  }
+
+  /// The value of a literal [expression], including adjacent and negative
+  /// forms, or null when the expression is not a plain literal.
+  static Object? literalValue(dart_ast.Expression? expression) {
+    if (expression is dart_ast.SimpleStringLiteral) {
+      return expression.value;
+    }
+    if (expression is dart_ast.AdjacentStrings) {
+      final StringBuffer buffer = StringBuffer();
+      for (final dart_ast.StringLiteral literal in expression.strings) {
+        final Object? part = literalValue(literal);
+        if (part is! String) {
+          return null;
+        }
+        buffer.write(part);
+      }
+      return buffer.toString();
+    }
+    if (expression is dart_ast.IntegerLiteral) {
+      return expression.value;
+    }
+    if (expression is dart_ast.DoubleLiteral) {
+      return expression.value;
+    }
+    if (expression is dart_ast.BooleanLiteral) {
+      return expression.value;
+    }
+    if (expression is dart_ast.PrefixExpression) {
+      final Object? operand = literalValue(expression.operand);
+      if (expression.operator.lexeme == '-') {
+        if (operand is int) {
+          return -operand;
+        }
+        if (operand is double) {
+          return -operand;
+        }
+      }
+      if (expression.operator.lexeme == '!' && operand is bool) {
+        return !operand;
+      }
+    }
+    return null;
+  }
+
+  @override
+  void visitTopLevelVariableDeclaration(dart_ast.TopLevelVariableDeclaration node) {
+    final dart_ast.VariableDeclarationList list = node.variables;
+    final bool constantSemantics =
+        list.isConst ||
+        list.isLate ||
+        list.isFinal ||
+        (list.keyword == null && list.type != null) ||
+        (list.keyword == null &&
+            list.variables.every(
+              (dart_ast.VariableDeclaration variable) =>
+                  _readDesugaredVarLiteral(variable.initializer!) != null,
+            ));
+    if (constantSemantics) {
+      for (final dart_ast.VariableDeclaration variable in list.variables) {
+        final dart_ast.Expression? initializer = variable.initializer;
+        if (initializer == null) {
+          continue;
+        }
+        final Object? value = list.isConst || list.isFinal
+            ? literalValue(initializer)
+            : _readDesugaredVarLiteral(initializer);
+        if (value != null) {
+          values[variable.name.lexeme] = value;
+        }
+      }
+    }
+    super.visitTopLevelVariableDeclaration(node);
+  }
+}

