+class AdvancedScenarioMockTransport implements Transport {
+  final List<JsonRpcMessage> sentMessages = [];
+  bool _closed = false;
+
+  @override
+  String? get sessionId => null;
+
+  @override
+  void Function()? onclose;
+
+  @override
+  void Function(Error error)? onerror;
+
