+      transport.emit(const JsonRpcInitializedNotification());
+      await _settle();
+      expect(errors, isNotEmpty);
+
+      transport.emit(const JsonRpcListToolsRequest(id: 33));
+      await _settle();
+      expect(handlerCalled, isFalse);
+
+      await server.close();
+    });
