diff --git a/packages/riverpod/test/src/core/action_test.dart b/packages/riverpod/test/src/core/action_test.dart
new file mode 100644
index 00000000..e1738a30
--- /dev/null
+++ b/packages/riverpod/test/src/core/action_test.dart
@@ -0,0 +1,329 @@
+import 'dart:async';
+
+import 'package:mockito/mockito.dart';
+import 'package:riverpod/experimental/action.dart';
+import 'package:riverpod/experimental/mutation.dart';
+import 'package:riverpod/riverpod.dart';
+import 'package:test/test.dart' hide Retry;
+
+import '../matrix.dart';
+import '../utils.dart';
+
+void main() {
+  group('action', () {
+    test('resolves with the value returned by the callback', () async {
+      final result = await action(() async => 21);
+
+      expect(result, 21);
+    });
+
+    test('propagates synchronous and asynchronous errors', () async {
+      await expectLater(
+        action(() async => throw Exception('async')),
+        throwsA(isA<Exception>()),
+      );
+
+      expect(
+        action<int>(() => throw Exception('sync')),
+        throwsA(isA<Exception>()),
+      );
+    });
+
+    test(
+      'releases subscriptions opened through reads when the callback throws',
+      () async {
+        final container = ProviderContainer.test();
+        final onDispose = OnDisposeMock();
+        final provider = Provider.autoDispose<int>((ref) {
+          ref.onDispose(onDispose.call);
+          return 0;
+        });
+
+        final future = action(() async {
+          container.read(provider);
+
+          throw Exception('error');
+        });
+
+        await expectLater(future, throwsA(isA<Exception>()));
+        await container.pump();
+
+        verifyOnly(onDispose, onDispose());
+      },
+    );
+
+    test(
+      'dropping the mutation states keeps the provider-lifetime guarantee',
+      () async {
+        final container = ProviderContainer.test();
+        final onDispose = OnDisposeMock();
+        final valueCompleter = Completer<int>();
+        final provider = FutureProvider.autoDispose<int>((ref) {
+          ref.onDispose(onDispose.call);
+          return valueCompleter.future;
+        });
+        final gate = Completer<void>();
+
+        final future = action(() async {
+          final result = container.read(provider.future);
+
+          // The provider was accessed without tracking idle/pending/error/
+          // success states, yet the read survives until the workflow
+          // completes.
+          await gate.future;
+
+          return result;
+        });
+
+        await container.pump();
+
+        verifyZeroInteractions(onDispose);
+
+        valueCompleter.complete(42);
+        gate.complete();
+
+        await expectLater(future, completion(42));
+        await container.pump();
+
+        verifyOnly(onDispose, onDispose());
+      },
+    );
+
+    test(
+      'keeps autoDispose providers read through ProviderContainer.read active '
+      'while the callback is pending, then releases them',
+      () async {
+        final container = ProviderContainer.test();
+        final onDispose = OnDisposeMock();
+        final valueCompleter = Completer<int>();
+        final provider = FutureProvider.autoDispose<int>((ref) {
+          ref.onDispose(onDispose.call);
+          return valueCompleter.future;
+        });
+
+        final gate = Completer<void>();
+        final future = action(() async {
+          final result = container.read(provider.future);
+
+          // The provider is accessed only inside the action, but the read
+          // subscription survives until the action completes.
+          await gate.future;
+
+          return result;
+        });
+
+        await container.pump();
+
+        // While the action is pending, the provider is kept alive.
+        verifyZeroInteractions(onDispose);
+
+        valueCompleter.complete(42);
+        gate.complete();
+
+        await expectLater(future, completion(42));
+        await container.pump();
+
+        // Once the action completed, its subscriptions were closed, so the
+        // otherwise unused autoDispose provider is disposed.
+        verifyOnly(onDispose, onDispose());
+      },
+    );
+
+    test('a plain ProviderContainer.read outside an action does not keep '
+        'autoDispose providers alive', () async {
+      final container = ProviderContainer.test();
+      final onDispose = OnDisposeMock();
+      final provider = FutureProvider.autoDispose<int>((ref) {
+        ref.onDispose(onDispose.call);
+        return Future.value(42);
+      });
+
+      unawaited(container.read(provider.future));
+
+      await container.pump();
+
+      verifyOnly(onDispose, onDispose());
+    });
+
+    test('keeps autoDispose providers read through Ref.read active '
+        'while the callback is pending, then releases them', () async {
+      final container = ProviderContainer.test();
+      final onDispose = OnDisposeMock();
+      final valueCompleter = Completer<int>();
+      final provider = FutureProvider.autoDispose<int>((ref) {
+        ref.onDispose(onDispose.call);
+        return valueCompleter.future;
+      });
+
+      // A notifier owns its own state and cannot use mutations.
+      final notifier = DeferredNotifier<int>((ref, self) => 0);
+      final holder = NotifierProvider<DeferredNotifier<int>, int>(
+        () => notifier,
+      );
+      container.read(holder);
+
+      final gate = Completer<void>();
+      final future = action(() async {
+        final result = notifier.ref.read(provider.future);
+
+        await gate.future;
+
+        // The notifier's own ref is still usable after the async gap,
+        // within the scope of the action.
+        return result;
+      });
+
+      await container.pump();
+
+      verifyZeroInteractions(onDispose);
+
+      valueCompleter.complete(42);
+      gate.complete();
+
+      await expectLater(future, completion(42));
+      await container.pump();
+
+      verifyOnly(onDispose, onDispose());
+    });
+
+    test('nested actions reuse the outermost action', () async {
+      final container = ProviderContainer.test();
+      final onDispose = OnDisposeMock();
+      final provider = Provider.autoDispose<int>((ref) {
+        ref.onDispose(onDispose.call);
+        return 0;
+      });
+
+      final gate = Completer<void>();
+      final future = action(() async {
+        container.read(provider);
+
+        // A nested action reads the same provider within the outer action.
+        await action(() async {
+          container.read(provider);
+        });
+
+        // The nested action completed, but the outer one is still pending,
+        // so the provider is still kept alive.
+        await gate.future;
+      });
+
+      await container.pump();
+      verifyZeroInteractions(onDispose);
+
+      gate.complete();
+      await future;
+      await container.pump();
+
+      verifyOnly(onDispose, onDispose());
+    });
+  });
+
+  group('voidAction', () {
+    test('returns a callback that runs inside an action', () async {
+      final Future<int> Function() callback = voidAction(() async => 42);
+
+      await expectLater(callback(), completion(42));
+    });
+
+    test('propagates errors thrown by the callback', () async {
+      final callback = voidAction(() async => throw Exception('error'));
+
+      await expectLater(callback(), throwsA(isA<Exception>()));
+    });
+
+    test('preserves the provider-lifetime behavior of action', () async {
+      final container = ProviderContainer.test();
+      final onDispose = OnDisposeMock();
+      final valueCompleter = Completer<int>();
+      final provider = FutureProvider.autoDispose<int>((ref) {
+        ref.onDispose(onDispose.call);
+        return valueCompleter.future;
+      });
+      final gate = Completer<void>();
+
+      final callback = voidAction(() async {
+        final result = container.read(provider.future);
+
+        await gate.future;
+
+        return result;
+      });
+
+      final future = callback();
+
+      await container.pump();
+      verifyZeroInteractions(onDispose);
+
+      valueCompleter.complete(42);
+      gate.complete();
+
+      await expectLater(future, completion(42));
+      await container.pump();
+
+      verifyOnly(onDispose, onDispose());
+    });
+  });
+
+  group('Mutation regression', () {
+    test(
+      'Mutation.run resolves with the callback value and reports success',
+      () async {
+        final mut = Mutation<int>();
+        final container = ProviderContainer.test();
+
+        final result = await mut.run(container, () async => 42);
+
+        expect(result, 42);
+        expect(container.read(mut), isMutationSuccess<int>(42));
+      },
+    );
+
+    test('Mutation.run propagates errors and reports MutationError', () async {
+      final mut = Mutation<int>();
+      final container = ProviderContainer.test();
+
+      await expectLater(
+        mut.run(container, () async => throw Exception('error')),
+        throwsA(isA<Exception>()),
+      );
+
+      expect(
+        container.read(mut),
+        isMutationError<int>(error: isA<Exception>()),
+      );
+    });
+
+    test('Mutation.run keeps autoDispose providers read through the target '
+        'active until the end of the mutation', () async {
+      final mut = Mutation<int>();
+      final container = ProviderContainer.test();
+      final onDispose = OnDisposeMock();
+      final valueCompleter = Completer<int>();
+      final provider = FutureProvider.autoDispose<int>((ref) {
+        ref.onDispose(onDispose.call);
+        return valueCompleter.future;
+      });
+      final completer = Completer<void>();
+
+      final future = mut.run(container, () async {
+        final result = container.read(provider.future);
+
+        await completer.future;
+
+        return result;
+      });
+
+      await container.pump();
+      verifyZeroInteractions(onDispose);
+
+      valueCompleter.complete(42);
+      completer.complete();
+
+      await expectLater(future, completion(42));
+      await container.pump();
+
+      verifyOnly(onDispose, onDispose());
+    });
+  });
+}
