+
+/// Matches the title of the per-package dialog that lets the user select
+/// which of that package's skills to install or update.
+///
+/// The dialog title must make it clear that both installs and updates may be
+/// performed for the named package, e.g.
+/// `Select skills to install/update from package <package>:`.
+Matcher selectSkillsTitleForPackage(String package) => allOf([
+  contains('package $package'),
+  contains('install'),
+  contains('update'),
+]);
+
+/// Matches a dialog option for [skillName] annotated as a new skill.
+///
+/// The annotation must contain the word `new` (any capitalization), e.g.
+/// `foo (new)` or `foo (New)`.
+Matcher isNewSkillOption(String skillName) => _skillOption(skillName, 'new');
+
+/// Matches a dialog option for [skillName] annotated as having a published
+/// update available, e.g. `foo (Update available)`.
+Matcher isUpdateAvailableSkillOption(String skillName) =>
+    _skillOption(skillName, 'update');
+
+/// Matches a dialog option for [skillName] annotated as having local edits,
+/// e.g. `foo (Local edits)` or `foo (Locally edited)`.
+Matcher isLocalEditsSkillOption(String skillName) =>
+    _skillOption(skillName, 'local');
+
+/// Matches a dialog option for [skillName] annotated as removed from the
+/// source, e.g. `foo (Removed)`.
+Matcher isRemovedSkillOption(String skillName) =>
+    _skillOption(skillName, 'removed');
+
+/// Matches a dialog option for [skillName] annotated as previously skipped,
+/// e.g. `foo (Skipped previously)`.
+Matcher isSkippedPreviouslySkillOption(String skillName) =>
+    _skillOption(skillName, 'skipped');
+
+Matcher _skillOption(String skillName, String stateKeyword) =>
+    _SkillOptionMatcher(skillName, stateKeyword.toLowerCase());
+
+class _SkillOptionMatcher extends Matcher {
+  final String _skillName;
+  final String _stateKeywordLower;
+
+  const _SkillOptionMatcher(this._skillName, this._stateKeywordLower);
+
+  @override
+  bool matches(Object? item, Map matchState) {
+    if (item is! String) return false;
+    return item.contains(_skillName) &&
+        item.toLowerCase().contains(_stateKeywordLower);
+  }
+
+  @override
+  Description describe(Description description) => description.add(
+    'a string containing "$_skillName" '
+    'and (case-insensitive) "$_stateKeywordLower"',
+  );
+
+  @override
+  Description describeMismatch(
+    Object? item,
+    Description mismatchDescription,
+    Map matchState,
+    bool verbose,
+  ) => mismatchDescription.add(
+    '$item does not contain both "$_skillName" '
+    'and (case-insensitive) "$_stateKeywordLower"',
+  );
+}

