+    }
+
+    @discardableResult
+    private func run(_ executable: String, _ arguments: [String], in directory: URL, environment: [String: String] = [:], output: inout String?) throws -> Int32 {
+        let process = Process()
+        process.executableURL = URL(fileURLWithPath: executable)
+        process.arguments = arguments
+        process.currentDirectoryURL = directory
+        process.environment = ProcessInfo.processInfo.environment.merging(environment) { _, replacement in replacement }
+        // capture both streams: a review stop may be reported on stdout as well as stderr, and
+        // both are the release's diagnostics
+        let standardOutput = Pipe()
+        let standardError = Pipe()
+        process.standardOutput = standardOutput
+        process.standardError = standardError
+        try process.run()
+        // drain the diagnostics before reaping so a verbose script cannot fill a pipe and wedge
+        let outData = standardOutput.fileHandleForReading.readDataToEndOfFile()
+        let errData = standardError.fileHandleForReading.readDataToEndOfFile()
+        output = String(decoding: outData, as: UTF8.self) + String(decoding: errData, as: UTF8.self)
+        process.waitUntilExit()
+        return process.terminationStatus
+    }
