+    private func commandWords(in text: String) -> [[String]] {
+        text.components(separatedBy: .newlines).map { line in
+            var words: [String] = []
+            var word = ""
+            var quote: Character?
+            var quoted = false
+            for character in line {
+                if let active = quote {
+                    if character == active { quote = nil } else { word.append(character) }
+                } else if character == "'" || character == "\"" {
+                    quote = character
+                    quoted = true
+                } else if character.isWhitespace {
+                    if !word.isEmpty || quoted { words.append(word); word = ""; quoted = false }
+                } else {
+                    word.append(character)
+                }
+            }
+            if !word.isEmpty || quoted { words.append(word) }
+            return words
+        }
