+    // the skill's own location however the snippet expresses it — written out literally, as a
+    // placeholder in angle brackets, or through a variable whose name denotes the skill directory
+    // (but never a client plugin or marketplace root, which is not the skill's location in a
+    // Help-menu install) — and substituting the snippet's own assignments for other variables, so
+    // an instruction that first establishes the installed skill directory and then invokes scripts
+    // relative to it expands all the way. `workingDirectory` carries the directory the snippet
+    // itself established with an earlier change-directory word, when that directory is
+    // install-relative: a shell-maintained working-directory word such as `$PWD` then names that
+    // directory, since the shell keeps the two equal. The caller's home expands to `homeHint`,
+    // which is empty for a plugin install and the install's client home for a Help-menu copy.
+    // Returns nil when the expanded word still depends on the caller's environment (a client
+    // plugin root, a command substitution, a working directory the snippet did not establish):
+    // such a path names no install's helper for certain.
+    private func expanded(_ word: String, root: String, assignments: [String: String], homeHint: String, workingDirectory: String? = nil, depth: Int = 0) -> String? {
+        guard depth < 8 else { return nil }
+        var result = ""
+        var index = word.startIndex
+        while index < word.endIndex {
+            let character = word[index]
+            // A home-directory expansion anchors the path at the caller's client configuration
+            // home — where this Help-menu copy of the skill lives — never at a plugin install.
+            if character == "~" { guard !root.isEmpty else { return nil }; index = word.index(after: index); continue }
+            // A command substitution names no path until the caller's shell runs it.
+            if character == "$", word[word.index(after: index)...].hasPrefix("(") { return nil }
+            if character == "<", let close = word[index...].firstIndex(of: ">") {
+                result += root
+                index = word.index(after: close)
+                continue
+            }
+            if character == "$" {
+                var next = word.index(after: index)
+                var braced = false
+                if next < word.endIndex && word[next] == "{" { braced = true; next = word.index(after: next) }
+                let nameStart = next
+                while next < word.endIndex && (word[next].isLetter || word[next].isNumber || word[next] == "_") {
+                    next = word.index(after: next)
+                }
+                let name = String(word[nameStart..<next])
+                if braced {
+                    guard let close = word[next...].firstIndex(of: "}") else { return nil }
+                    next = word.index(after: close)
+                }
+                index = next
+                let lowered = name.lowercased()
+                if !name.isEmpty, lowered.contains("skill"), !lowered.contains("plugin"), !lowered.contains("home") {
+                    // A variable that denotes the skill directory stands for that directory:
+                    // the snippet's own assignment establishing it, or the directory itself.
+                    let value = assignments[name] ?? root
+                    guard let value = expanded(value, root: root, assignments: assignments, homeHint: homeHint, workingDirectory: workingDirectory, depth: depth + 1) else { return nil }
+                    result += value
+                } else if !name.isEmpty, let value = assignments[name],
+                          let value = expanded(value, root: root, assignments: assignments, homeHint: homeHint, workingDirectory: workingDirectory, depth: depth + 1) {
+                    result += value
+                } else if lowered == "pwd" || lowered == "oldpwd", let workingDirectory {
+                    // A shell-maintained working-directory word names the directory the snippet
+                    // itself established earlier — but only when that directory already expanded
+                    // install-relative, so the word relocates with the install rather than naming
+                    // whatever directory the caller happened to stand in.
+                    result += workingDirectory
+                } else if !name.isEmpty, lowered.contains("home") || lowered == "userprofile" {
+                    // The caller's client configuration home resolves only for a Help-menu
+                    // copy, which lives there.
+                    guard !root.isEmpty else { return nil }
+                    result += homeHint
+                } else {
+                    return nil
+                }
+                continue
+            }
+            result.append(character)
+            index = word.index(after: index)
+        }
+        return result
+    }
+
+    // A documented command resolves the helper from its own install when, read as shell against
+    // the install laid out at `installedSkill`, one of its words expands to that install's copy of
+    // the helper. Expansions anchored at the installed skill directory itself — written literally,
+    // through a placeholder, through a variable whose name denotes the skill directory, or through
+    // the snippet's own assignment establishing that directory — relocate with the skill and
+    // qualify from every layout. An instruction that first establishes the installed skill
+    // directory — changes into it — and then invokes the helper qualifies too, whether it names
+    // the helper by a relative path or through the shell's working directory (`$PWD`), since a
+    // change into the skill directory keeps both install-relative. A home-anchored expansion
+    // qualifies only for a Help-menu copy, which lives in the caller's client home; `clientHome`
+    // supplies that home for such a copy and is empty for a plugin install. A path rooted at a
+    // client plugin or marketplace root, or one depending on a command substitution or another
+    // environment variable, names no install's helper for certain and never qualifies.
+    private func documentedHelper(in text: String, installedSkill: URL, clientHome: String = "") -> URL? {
+        let root = installedSkill.path
+        let helper = installedSkill.appendingPathComponent("scripts/show-image.sh").path
+        // Prose can also establish the directory outright: documentation that states the helper is
+        // run from the skill's installed directory — the directory containing SKILL.md — and then
+        // invokes it by its relative path resolves install-relative without a literal `cd` word.
+        if establishesSkillDirectoryAsWorkingDirectory(in: text),
+           commandWords(in: text).flatMap({ $0 }).contains(where: { $0 == "scripts/show-image.sh" }) {
+            return URL(fileURLWithPath: helper)
+        }
+        var assignments: [String: String] = [:]
+        for word in commandWords(in: text).flatMap({ $0 }) {
+            guard let equal = word.firstIndex(of: "="), equal > word.startIndex else { continue }
+            let name = word[..<equal]
+            guard name.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }) else { continue }
+            assignments[String(name)] = String(word[word.index(after: equal)...])
+        }
+        // Read the snippet as the shell documents it: changing directory persists for the commands
+        // that follow, so a helper invoked by a relative path, or through the shell-maintained
+        // working directory, resolves against the directory the snippet established. A change
+        // whose target cannot be expanded leaves the directory unknown, and a change into a
+        // layout-specific target expands relative words only under the layout that target names.
+        var workingDirectory: String?
+        for words in commandWords(in: text) {
+            var directoryChange = false
+            for word in words {
+                if word == "cd" {
+                    directoryChange = true
+                    continue
+                }
+                if directoryChange {
+                    workingDirectory = expanded(word, root: root, assignments: assignments, homeHint: clientHome, workingDirectory: workingDirectory)
+                    directoryChange = false
+                }
+                if let workingDirectory, isRelativePath(word),
+                   normalizedPath(workingDirectory + "/" + word) == helper {
+                    return URL(fileURLWithPath: helper)
+                }
+                guard expanded(word, root: root, assignments: assignments, homeHint: clientHome, workingDirectory: workingDirectory) == helper else { continue }
+                return URL(fileURLWithPath: helper)
+            }
+        }
+        return nil
+    }
+
+    // Whether the prose itself establishes the installed skill directory as the working
+    // directory for the documented commands: an explicit statement that the command is run from
+    // the skill's installed directory or the directory containing SKILL.md. Such a statement is
+    // install-relative by construction, since the installed directory relocates with the skill.
+    private func establishesSkillDirectoryAsWorkingDirectory(in text: String) -> Bool {
+        let normalized = text.lowercased().components(separatedBy: .newlines)
+            .map { $0.replacingOccurrences(of: "`", with: "") }
+            .joined(separator: "\n")
+        let square = CharacterSet.alphanumerics.inverted
+        for line in normalized.components(separatedBy: "\n") {
+            let words = line.components(separatedBy: square).filter { !$0.isEmpty }
+            guard !words.isEmpty else { continue }
+            let tokens = words.filter { $0 != "to" && $0 != "s" && $0 != "of" }
+            let namesSkill = tokens.contains("skill")
+                || tokens.contains("directory")
+                || tokens.contains("dir")
+                || tokens.contains("installation")
+                || tokens.contains("install")
+                || tokens.contains("installed")
+                || tokens.contains("installs")
+            let namesMarker = words.contains("of") && words.contains("skill") && words.contains("md")
+                || line.contains("md>")
+            guard namesSkill || namesMarker else { continue }
+            let anchors = tokens.contains("installed")
+                || tokens.contains("install")
+                || tokens.contains("installation")
+                || tokens.contains("installs")
+                || tokens.contains("location")
+                || tokens.contains("containing")
+                || tokens.contains("contains")
+                || (tokens.contains("directory") && tokens.contains("skill"))
+            // prose about a fixed home or client plugin layout spells out where the skill lands,
+            // not a working directory to run the helper from
+            guard !tokens.contains("home"), !tokens.contains("plugin"), !tokens.contains("plugins") else { continue }
+            guard anchors else { continue }
+            return true
+        }
+        return false
+    }
+
+    // A word that reads as a path relative to the directory the command is run from.
+    private func isRelativePath(_ word: String) -> Bool {
+        word.contains("/") && !word.hasPrefix("/") && !word.hasPrefix("~") && !word.hasPrefix("$") && !word.hasPrefix("<")
+    }
+
+    // Collapses "." and ".." steps in a literal path; returns nil when a step climbs above the root.
+    private func normalizedPath(_ path: String) -> String? {
+        var parts: [String] = []
+        for component in path.split(separator: "/", omittingEmptySubsequences: true) {
+            if component == "." { continue }
+            if component == ".." {
+                guard !parts.isEmpty else { return nil }
+                parts.removeLast()
+                continue
+            }
+            parts.append(String(component))
+        }
+        return "/" + parts.joined(separator: "/")
+    }
+
+    // Every file in the authoritative skill tree travels with the plugin: SKILL.md, the reference,
+    // the examples, the troubleshooting guide, and the image helper.
+    private let requiredSkillFiles = ["SKILL.md", "reference.md", "examples.md", "troubleshooting.md", "scripts/show-image.sh"]
+
+    private func pluginEntry(in marketplace: [String: Any], from label: String) throws -> [String: Any] {
+        guard let entries = marketplace["plugins"] as? [[String: Any]],
+              let entry = entries.first(where: { $0["name"] as? String == SkillInstall.skillName }) else {
+            throw ContractError.invalid("\(label) does not publish \(SkillInstall.skillName)")
+        }
+        return entry
+    }
+
+    // A JSON value that names a local directory: either the string itself, or an object carrying
+    // the path under one of its string-valued keys, so both a plain "./plugins/agterm" source and
+    // a {"source": "local", "path": "./plugins/agterm"} source resolve here to the same package.
+    private func localPath(appendingTo value: Any?) -> String? {
+        if let path = value as? String { return path }
+        if let object = value as? [String: Any],
+           let source = object["source"] as? String, source == "local",
+           let path = object["path"] as? String, !path.isEmpty {
+            return path
+        }
+        return nil
+    }
+
+    // Resolves a local path spelling component by component. Spellings that stay at or under the
+    // base — ".", "./", "plugins/agterm", and paths that step up but never above the base — all
+    // qualify, so a repository-root package ("./") resolves to the empty component list. A spelling
+    // that climbs above the base is always an error, never silently absorbed, no matter where the
+    // upward step occurs, and absolute or remote spellings never qualify.
+    private func resolve(_ spelling: String?, under base: [String], _ what: String, allowUpward: Bool) throws -> [String] {
+        guard let spelling, !spelling.isEmpty, !spelling.hasPrefix("/"), !spelling.contains("://") else {
+            throw ContractError.invalid("\(what) is not a repository-local path")
+        }
+        var components = base
+        for part in spelling.split(separator: "/") {
+            switch part {
+            case ".", "":
+                continue
+            case "..":
+                guard allowUpward, !components.isEmpty else {
+                    throw ContractError.invalid("\(what) escapes its base directory")
+                }
+                components.removeLast()
+            default:
+                components.append(String(part))
+            }
+        }
+        return components
+    }
+
+    private func resolveInRepo(_ spelling: String?, _ what: String) throws -> [String] {
+        try resolve(spelling, under: [], what, allowUpward: true)
+    }
+
+    private func relativePath(of components: [String]) -> String {
+        components.joined(separator: "/")
+    }
+
+    private func isWithin(_ tree: [String], _ root: [String]) -> Bool {
+        tree.count >= root.count && Array(tree.prefix(root.count)) == root
+    }
+
+    private func canonicalComponents(_ url: URL) -> [String] {
+        url.standardizedFileURL.resolvingSymlinksInPath().pathComponents
+    }
+
+    // Resolve a repository/package-relative path through symlinks and reject a target that escapes
+    // its declared root. Lexical normalization alone is insufficient for plugin source and skill
+    // pointers because a harmless-looking component may be a symlink to an external tree.
+    private func resolveFilesystemPath(_ spelling: String, under base: URL, containedBy root: URL) -> URL? {
+        guard !spelling.hasPrefix("/"), !spelling.contains("://") else { return nil }
+        let candidate = URL(fileURLWithPath: base.path + "/" + spelling).standardizedFileURL.resolvingSymlinksInPath()
+        let canonicalRoot = root.standardizedFileURL.resolvingSymlinksInPath()
+        return isWithin(canonicalComponents(candidate), canonicalComponents(canonicalRoot)) ? candidate : nil
+    }
+
+    // Offline validation of the metadata shape consumed by each plugin manager. The source
+    // encoding is client-native (Claude accepts a local path; Codex's marketplace form uses the
+    // local/path object), and the validator intentionally does not share the generic path reader
+    // used by package() above.
+    private func claudeMarketplaceIsDiscoverable(_ value: Any) -> Bool {
+        guard let root = value as? [String: Any],
+              root["name"] as? String == SkillInstall.skillName,
+              let owner = root["owner"] as? [String: Any],
+              let ownerName = owner["name"] as? String, !ownerName.isEmpty,
+              let plugins = root["plugins"] as? [[String: Any]],
+              let plugin = plugins.first(where: { $0["name"] as? String == SkillInstall.skillName }),
+              plugin["description"] as? String != nil,
+              plugin["version"] as? String != nil else { return false }
+        let source = plugin["source"]
+        if let path = source as? String {
+            return !path.isEmpty && !path.hasPrefix("/") && !path.contains("://")
+        }
+        if let local = source as? [String: Any] {
+            return local["source"] as? String == "local" && (local["path"] as? String) != nil
+        }
+        return false
+    }
+
+    private func pluginManifestIsDiscoverable(_ value: Any) -> Bool {
+        guard let manifest = value as? [String: Any],
+              manifest["name"] as? String == SkillInstall.skillName,
+              let version = manifest["version"] as? String, !version.isEmpty else { return false }
+        if let path = manifest["skills"] as? String { return !path.isEmpty }
+        if let paths = manifest["skills"] as? [String] { return !paths.isEmpty && paths.allSatisfy { !$0.isEmpty } }
+        return false
+    }
+
+    private func codexMarketplaceIsDiscoverable(_ value: Any) -> Bool {
+        guard let root = value as? [String: Any],
+              let plugins = root["plugins"] as? [[String: Any]],
+              let plugin = plugins.first(where: { $0["name"] as? String == SkillInstall.skillName }),
+              let source = localPath(appendingTo: plugin["source"]),
+              !source.hasPrefix("/"), !source.contains("://") else { return false }
+        return true
+    }
+
+    // A manifest's skill pointer is a single string or the first entry of a string array. The
+    // spelling may read as relative to the published package root or to the manifest's own
+    // directory — both forms are in use — so the accepted reading is the one that names an
+    // existing skill tree inside the package (or, for a client that discovers skills by container
+    // directory, the directory holding it). A spelling that climbs above the repository, escapes
+    // the package, or names nothing is invalid.
+    private func skillTree(of manifest: [String: Any], package: [String], manifestDirectory: [String], allowParentContainer: Bool, _ label: String) throws -> [String] {
+        let spelling: String
+        if let path = manifest["skills"] as? String, !path.isEmpty {
+            spelling = path
+        } else if let paths = manifest["skills"] as? [String], let first = paths.first(where: { !$0.isEmpty }) {
+            spelling = first
+        } else {
+            throw ContractError.invalid("\(label) names no skill tree")
+        }
+        for base in [package, manifestDirectory] {
+            guard let resolved = try? resolve(spelling, under: base, "\(label) skill path", allowUpward: true),
+                  isWithin(resolved, package) else { continue }
+            guard resolveFilesystemPath(relativePath(of: resolved), under: repository,
+                                        containedBy: repository.appendingPathComponent(relativePath(of: package))) != nil else { continue }
+            if fileExists(relativePath(of: resolved + ["SKILL.md"])) { return resolved }
+            if allowParentContainer,
+               fileExists(relativePath(of: resolved + [SkillInstall.skillName, "SKILL.md"])) { return resolved }
+        }
+        throw ContractError.invalid("\(label) skill path names no skill tree inside the published package")
+    }
+
+    private func allSkillPointersResolveToAuthoritativeTree(_ manifest: [String: Any],
+                                                            package components: [String],
+                                                            manifestDirectory: [String],
+                                                            authoritativeTree: [String],
+                                                            allowParentContainer: Bool) -> Bool {
+        let pointers: [String]
+        if let single = manifest["skills"] as? String { pointers = [single] }
+        else if let many = manifest["skills"] as? [String] { pointers = many }
+        else { return false }
+        guard !pointers.isEmpty else { return false }
+        let packageRoot = repository.appendingPathComponent(relativePath(of: components))
+        return pointers.allSatisfy { spelling in
+            for base in [components, manifestDirectory] {
+                guard let resolved = try? resolve(spelling, under: base, "plugin skill path", allowUpward: true),
+                      isWithin(resolved, components),
+                      resolveFilesystemPath(relativePath(of: resolved), under: repository, containedBy: packageRoot) != nil else { continue }
+                if resolved == authoritativeTree { return true }
+                if allowParentContainer && resolved + [SkillInstall.skillName] == authoritativeTree { return true }
+            }
+            return false
+        }
+    }
+
+    // The package the root marketplace publishes: the one discovery every file-format contract
+    // shares, so no test hand-rolls its own reading of the source spelling. The Codex plugin
+    // manifest adjacent to the Claude one is what Codex plugin discovery reads for this repository.
+    private func package() throws -> (components: [String], path: String, claudeManifest: [String: Any], codexManifest: [String: Any], skillTree: [String]) {
+        let marketplace = try json(".claude-plugin/marketplace.json")
+        let entry = try pluginEntry(in: marketplace, from: ".claude-plugin/marketplace.json")
+        let components = try resolveInRepo(localPath(appendingTo: entry["source"]), "marketplace source")
+        let canonicalRepositoryPackage = resolveFilesystemPath(relativePath(of: components), under: repository, containedBy: repository)
+        guard canonicalRepositoryPackage != nil else {
+            throw ContractError.invalid("marketplace source resolves outside the repository")
+        }
+        let claude = try json(relativePath(of: components + [".claude-plugin", "plugin.json"]))
+        guard claude["name"] as? String == SkillInstall.skillName else {
+            throw ContractError.invalid("Claude plugin identity does not match the skill")
+        }
+        let codex = try json(relativePath(of: components + [".codex-plugin", "plugin.json"]))
+        guard codex["name"] as? String == SkillInstall.skillName else {
+            throw ContractError.invalid("Codex plugin discovery finds no plugin manifest for the skill")
+        }
+        let tree = try skillTree(of: claude, package: components, manifestDirectory: components + [".claude-plugin"], allowParentContainer: false, "Claude plugin.json")
+        return (components, relativePath(of: components), claude, codex, tree)
+    }
+
+    @Test func marketplacesPublishOneCompleteSkillPackageForBothAgents() throws {
+        guard fileExists(".claude-plugin/marketplace.json") else {
+            #expect(false, "the root Claude marketplace descriptor is missing")
+            return
+        }
+        guard let package = try? package() else {
+            #expect(false, "the root marketplace does not resolve to an in-repository plugin package")
+            return
+        }
+
+        // the Claude side resolves its skill pointer inside the published package
+        let skill = package.skillTree
+        #expect(allSkillPointersResolveToAuthoritativeTree(package.claudeManifest,
+                                                           package: package.components,
+                                                           manifestDirectory: package.components + [".claude-plugin"],
+                                                           authoritativeTree: skill, allowParentContainer: false),
+                "the Claude manifest contains a pointer that does not resolve to the authoritative package skill")
+        #expect(isWithin(skill, package.components), "the Claude skill tree is not inside the published package")
+        for file in requiredSkillFiles {
+            #expect(fileExists(relativePath(of: skill + file.split(separator: "/").map(String.init))),
+                    "the published skill is missing \(file)")
+        }
+
+        // the Codex plugin manifest — the repository's Codex plugin discovery descriptor — resolves
+        // the same tree as the Claude plugin, so one authored skill body serves both agents
+        #expect(allSkillPointersResolveToAuthoritativeTree(package.codexManifest,
+                                                           package: package.components,
+                                                           manifestDirectory: package.components + [".codex-plugin"],
+                                                           authoritativeTree: skill, allowParentContainer: true),
+                "the Codex manifest contains a pointer that does not resolve the authoritative package skill")
+        if let codexTree = try? skillTree(of: package.codexManifest, package: package.components,
+                                         manifestDirectory: package.components + [".codex-plugin"],
+                                         allowParentContainer: true, "Codex plugin.json") {
+            #expect(codexTree == skill || isWithin(skill, codexTree),
+                    "the Codex skill pointer does not resolve the same tree as the Claude plugin")
+        } else {
+            #expect(false, "the Codex skill pointer does not resolve within the package")
+        }
+
+        // Every shipped discovery listing must describe this package via a supported local source.
+        // An additional listing is not allowed to be remote-only or silently ignored.
+        var listings = [".claude-plugin/marketplace.json"]
+        for candidate in [".agents/plugins/marketplace.json", ".codex-plugin/marketplace.json"] {
+            if fileExists(candidate) { listings.append(candidate) }
+        }
+        for listing in listings {
+            let entry = try pluginEntry(in: json(listing), from: listing)
+            guard let source = localPath(appendingTo: entry["source"]) else {
+                throw ContractError.invalid("\(listing) has no local package source")
+            }
+            guard let localComponents = try? resolveInRepo(source, "\(listing) source") else {
+                #expect(false, "\(listing) source escapes the repository or is not local")
+                continue
+            }
+            let localTarget = resolveFilesystemPath(relativePath(of: localComponents), under: repository, containedBy: repository)
+            let rootTarget = resolveFilesystemPath(package.path, under: repository, containedBy: repository)
+            #expect(localTarget == rootTarget,
+                    "\(listing) does not resolve the same package as the root marketplace")
+        }
+    }
