+    @Test func helpMenuInstallerShipsTheSameAuthoritativeSkillTree() throws {
+        // the fallback install path can only ship what the app bundle is handed, and every
+        // configuration step hands it the same authoritative tree the plugin manifests resolve
+        guard fileExists(".claude-plugin/marketplace.json") else {
+            #expect(false, "the packaged skill is missing")
+            return
+        }
+        let skill = relativePath(of: try authoredSkillTree())
+
+        // the build configuration hands that same tree to the app bundle — quoted, plain, or
+        // normalized spellings of the path all count, and no single configuration-file spelling
+        // is the only way to ship it
+        #expect(try appResourceBuildPhaseContains(skillTree: skill),
+                "the app resource build phase does not bundle the authoritative skill tree")
+        // and it is literally the same skill: whichever trees the two install routes read, they
+        // carry identical contents file for file, so neither route silently ships a stale or
+        // trimmed skill
+        guard let publishedPackage = try? package() else {
+            #expect(false, "the published plugin package has no authoritative skill tree")
+            return
+        }
+        let resolvedTree = relativePath(of: publishedPackage.skillTree)
+        let helpMenuTree = relativePath(of: try authoredSkillTree())
+        for file in requiredSkillFiles {
+            let published = resolvedTree.isEmpty ? file : resolvedTree + "/" + file
+            let fallback = helpMenuTree + "/" + file
+            #expect(fileExists(fallback), "the Help-menu skill is missing \(file)")
+            #expect(try fileContents(published) == fileContents(fallback),
+                    "the published skill's \(file) differs from the Help-menu skill")
+        }
+    }
