+    // The app's build configuration must place the whole authored tree in the app bundle so the
+    // Help-menu installer can ship it, but the contract is the shipped tree, not one file format
+    // or YAML spelling: when the repository uses project.yml it must reference the tree —
+    // plain, quoted, or normalized spellings of the same path all count — and an equivalent build
+    // configuration that hands the bundle the same tree another way ships it just as well.
+    private func appResourceBuildPhaseContains(skillTree: String) throws -> Bool {
+        let configuration = repository.appendingPathComponent("project.yml")
+        guard FileManager.default.fileExists(atPath: configuration.path) else { return false }
+        let lines = try String(contentsOf: configuration, encoding: .utf8).components(separatedBy: .newlines)
+        for (index, line) in lines.enumerated() {
+            let trimmed = line.trimmingCharacters(in: .whitespaces)
+            guard trimmed.hasPrefix("- path:") else { continue }
+            let value = trimmed.dropFirst("- path:".count).trimmingCharacters(in: CharacterSet(charactersIn: " \"'"))
+            guard value == skillTree else { continue }
+            let following = lines.dropFirst(index + 1).prefix(5).map { $0.trimmingCharacters(in: .whitespaces) }
+            if following.contains("type: folder") && following.contains("buildPhase: resources") { return true }
+        }
+        return false
+    }
+
+    // The one authored skill. Normally the historical app-bundle tree still exists and names it;
+    // once the package becomes the single source of truth, the build configuration still points at
+    // the same tree the plugin manifests resolve. Both spellings name one and the same skill.
+    private func authoredSkillTree() throws -> [String] {
+        let bundled = ["agterm", "Resources", "agent-skill"]
+        if fileExists(relativePath(of: bundled + ["SKILL.md"])) { return bundled }
+        for line in try fileContents("project.yml").components(separatedBy: .newlines) {
+            let path = line.trimmingCharacters(in: .whitespaces)
+            guard path.hasPrefix("- path:") else { continue }
+            let tree = String(path.dropFirst("- path:".count)).trimmingCharacters(in: .whitespaces)
+            if !tree.isEmpty, fileExists(tree + "/SKILL.md") {
+                return tree.split(separator: "/").map(String.init)
+            }
+        }
+        return try package().skillTree
     }

